function resetGraphExecution(owner){for(const e of world.entities.filter(e=>e.toolId===owner)){delete e.navigation;delete e.acceptedMessage;delete e.utilityMemory;delete e.sequenceMemory;delete e.waitTimers;}}
function renderGraph(){const select=$('brainTool');select.innerHTML=selectOptions(world.tools,toolId,'Choose an object type');select.onchange=()=>{toolId=select.value;entityId=world.entities.find(e=>e.toolId===toolId)?.id??null;connecting=null;renderGraph();renderInspector();renderTools();draw();};const t=tool();const instances=world.entities.filter(e=>e.toolId===t?.id);$('brainInstance').innerHTML=selectOptions(instances.map((e,i)=>({id:e.id,name:(i+1)+'. '+(t?.name??'Object')})),entity()?.toolId===t?.id?entityId:'','First placed instance');$('brainInstance').onchange=()=>{entityId=$('brainInstance').value||null;renderInspector();draw();updateBrainStatus(true);};if(!t){$('brainLiveStatus').textContent='Choose an object type to inspect.';$('brainContent').innerHTML=empty('Empty');return;}$('brainContent').innerHTML=`<div class="brain-controls"><label><input id="enableBrain" type="checkbox" ${t.brainEnabled?'checked':''}> Run this behavior tree</label><span>${t.brainEnabled?'Tree controls this object type':'Standalone utility decisions control this object type'}</span><button id="brainRun">${running?'Pause':'Run'}</button><button id="brainStep">Step</button></div><details class="brain-editing-tools" id="brainEditingTools" ${graphToolsOpen||!isSplitWorkspace()?'open':''}><summary>Graph controls</summary><div class="brain-controls"><select id="newNodeType" aria-label="New node type">${options([['sequence','Sequence'],['selector','Selector / fallback'],['utility','Utility selector'],['condition','Condition'],['action','Action']],'sequence')}</select><button id="addBrainNode">＋ Add node</button><button id="importDecisions">Graph from utility decisions</button>${t.kind==='creature'?'<button id="graphCreatureBranch">＋ Scored behavior branch</button><button id="graphCreatureSetup">Creature stats & tags</button>':''}</div></details><div class="brain-watch-controls"><label><input id="brainFollow" type="checkbox" ${followActive?'checked':''}> Follow running node</label><button id="brainCenter">Center current node</button><span class="brain-legend">RUNNING · SUCCESS · FAILURE</span></div><div id="brainGraph"><svg id="brainWires"></svg><div id="brainNodes"></div></div><div class="compact graph-note" id="connectionHint">${connecting?'Choose an input to finish connecting.':'Disconnected nodes do not run. Tree results appear as success, failure, or running.'}</div>`;
$('brainEditingTools').ontoggle=()=>{graphToolsOpen=$('brainEditingTools').open;};$('brainFollow').onchange=()=>{followActive=$('brainFollow').checked;};$('brainCenter').onclick=()=>followBrainNode(true);if(t.kind==='creature'){$('graphCreatureBranch').onclick=()=>editCreatureUtility(t.id);$('graphCreatureSetup').onclick=()=>editTool(t.id);}$('enableBrain').onchange=e=>{checkpoint();t.brainEnabled=e.target.checked;changed();renderGraph();};$('brainRun').onclick=()=>{$('play').click();$('brainRun').textContent=running?'Pause':'Run';};$('brainStep').onclick=()=>{$('step').click();updateBrainStatus();};$('addBrainNode').onclick=()=>{if(t.brain.length>=60)return toast('Prototype limit: 60 nodes per object type.');checkpoint();const n=makeNode($('newNodeType').value);n.x=330+Math.floor((t.brain.length-1)/5)*245;n.y=30+((t.brain.length-1)%5)*140;t.brain.push(n);changed();renderGraph();editBrainNode(t.id,n.id);};$('importDecisions').onclick=()=>{if(!t.decisions.some(d=>d.enabled))return toast('Create an enabled utility decision on this object type first.');modal('Build graph from utility decisions?',`<div class="dialog-actions"><button id="cancelGraphImport">Cancel</button><button class="primary" id="confirmGraphImport">Build graph</button></div>`);$('cancelGraphImport').onclick=()=>$('dialog').close();$('confirmGraphImport').onclick=()=>{checkpoint();const root=makeNode('utility','root');t.brain=[root];t.edges=[];for(const [i,d]of t.decisions.filter(d=>d.enabled).entries()){const n=Object.assign(makeNode('action'),{label:d.name,scoreStat:d.stat,direction:d.direction,weight:d.enabled?d.weight:0,action:d.action,targetTool:d.targetTool,x:340,y:25+i*140});t.brain.push(n);t.edges.push(['root',n.id]);}t.brainEnabled=true;connecting=null;changed();$('dialog').close();renderGraph();};};
$('brainNodes').innerHTML=t.brain.map(n=>`<div class="brain-node" data-node="${n.id}" style="left:${n.x*GRAPH_X}px;top:${n.y*GRAPH_Y}px"><div class="brain-node-head">${n.type.toUpperCase()} <span class="node-result" data-result="${n.id}"></span></div><div class="brain-node-body"><strong title="${esc(n.label)}">${esc(n.label)}</strong><small title="${esc(nodeSummary(n))}">${esc(nodeSummary(n))}</small><button data-edit-node="${n.id}">Edit</button></div>${n.id!=='root'?`<button class="brain-port input" data-node-input="${n.id}" aria-label="Connect input of ${esc(n.label)}"></button>`:''}${['sequence','selector','utility'].includes(n.type)?`<button class="brain-port output ${connecting===n.id?'pending':''}" data-node-output="${n.id}" aria-label="Connect output of ${esc(n.label)}"></button>`:''}</div>`).join('');$('brainNodes').querySelectorAll('[data-edit-node]').forEach(b=>b.onclick=()=>editBrainNode(t.id,b.dataset.editNode));$('brainNodes').querySelectorAll('[data-node-output]').forEach(b=>b.onclick=()=>{connecting=b.dataset.nodeOutput;$('connectionHint').textContent='Now click a node input. Escape cancels.';renderGraph();});$('brainNodes').querySelectorAll('[data-node-input]').forEach(b=>b.onclick=()=>{if(!connecting)return toast('Click a parent output first.');if(!canConnect(t,connecting,b.dataset.nodeInput))return toast('That connection is invalid or creates a cycle.');checkpoint();resetGraphExecution(t.id);t.edges.push([connecting,b.dataset.nodeInput]);connecting=null;changed();renderGraph();});$('brainNodes').querySelectorAll('.brain-node').forEach(el=>{el.ondblclick=()=>editBrainNode(t.id,el.dataset.node);el.onpointerdown=e=>{if(e.target.closest('button'))return;setRunning(false);checkpoint();const node=t.brain.find(n=>n.id===el.dataset.node);graphDrag={node,el,x:e.clientX-node.x*GRAPH_X,y:e.clientY-node.y*GRAPH_Y};el.setPointerCapture(e.pointerId);};});renderBrainWires();updateBrainStatus();}
function nodeSummary(n){if(n.type==='sequence')return n.sequenceMode==='memory'?'Continue running child, then advance':'Recheck children every tick';if(n.type==='condition'&&n.condition==='target')return (n.slot??'destination')+' · '+(n.targetCheck??'present');if(n.type==='action'&&['chooseTarget','moveTarget','rememberTarget','clearTarget','acknowledge'].includes(n.action))return n.action+' · '+(n.slot??'destination');if(n.type==='action'&&n.action==='wait')return (n.waitMin??2)+'–'+(n.waitMax??6)+' ticks';if(n.type==='action'&&n.action==='patrol')return 'Choose among '+(n.patrolZones?.length??0)+' areas · '+(n.routeStyle??'shortest')+' routes';if(n.type==='condition'&&n.condition==='message')return 'Message '+n.messageKey+' · '+n.messageCheck;if(n.type==='action'&&n.action==='directive')return 'Follow '+n.messageKey;if(n.type==='condition'&&n.condition==='zone')return (world.zones.find(z=>z.id===n.zoneId)?.name??'Choose zone')+' · '+n.zoneMode;if(n.type==='action'&&n.action==='zone')return 'Go to '+(world.zones.find(z=>z.id===n.zoneId)?.name??'zone');if(n.type==='condition')return n.condition==='tag'?`${tagDef(n.tag)?.name??'Choose tag'} ${n.tagMode}`:`${world.stats.find(s=>s.id===n.stat)?.name??'Choose stat'} ${n.op} ${n.threshold}`;if(n.type==='action')return n.action==='rule'?tool()?.rules.find(r=>r.id===n.ruleId)?.name??'Choose rule':n.action;return n.type==='utility'?'Score children, try strongest first':n.type==='sequence'?'Run children in order until failure':'Try children until one succeeds';}
function renderBrainWires(){const t=tool();if(!t||!$('brainWires'))return;const width=Math.max(1800,...t.brain.map(n=>n.x*GRAPH_X+330)),height=Math.max(1500,...t.brain.map(n=>n.y*GRAPH_Y+230));for(const id of ['brainWires','brainNodes']){ $(id).style.width=width+'px';$(id).style.height=height+'px';}$('brainWires').innerHTML=t.edges.map(([a,b],i)=>{const from=t.brain.find(n=>n.id===a),to=t.brain.find(n=>n.id===b);if(!from||!to)return '';const x=from.x*GRAPH_X+GRAPH_NODE_WIDTH,y=from.y*GRAPH_Y+GRAPH_PORT_Y,tx=to.x*GRAPH_X,ty=to.y*GRAPH_Y+GRAPH_PORT_Y;return `<path class="brain-wire" data-brain-edge="${i}" d="M ${x} ${y} C ${x+80} ${y}, ${tx-80} ${ty}, ${tx} ${ty}"/>`;}).join('');$('brainWires').querySelectorAll('path').forEach(p=>p.onclick=()=>{checkpoint();resetGraphExecution(t.id);t.edges.splice(Number(p.dataset.brainEdge),1);changed();renderGraph();});}
function watchedEntity(){const t=tool();return entity()?.toolId===t?.id?entity():world.entities.find(e=>e.toolId===t?.id);}
function updateBrainStatus(follow=false){if(!treeVisible())return;if($('brainRun'))$('brainRun').textContent=running?'Pause':'Run';const t=tool(),e=watchedEntity();$('brainLiveStatus').textContent=e?'Tick '+world.tick+' · '+(t?.name??'Object')+' ('+e.x+', '+e.y+') · '+e.action:'No placed instance of this object type. Draw one on the board to watch it.';$('brainNodes')?.querySelectorAll('.brain-node').forEach(el=>{const result=e?.nodeStatus?.[el.dataset.node]??'';el.classList.toggle('visited',Boolean(result));for(const state of ['running','success','failure'])el.classList.toggle('state-'+state,result===state);el.dataset.state=result;const badge=$('brainNodes').querySelector('[data-result="'+el.dataset.node+'"]');if(badge)badge.textContent=result?result.toUpperCase():'';});$('brainWires')?.querySelectorAll('[data-brain-edge]').forEach(el=>{const edge=t?.edges[Number(el.dataset.brainEdge)],result=edge?e?.nodeStatus?.[edge[1]]:'';el.classList.toggle('wire-running',result==='running');el.classList.toggle('wire-failure',result==='failure');});if(follow&&followActive)followBrainNode();}
function followBrainNode(force=false){if(!treeVisible()||!force&&!followActive)return;const t=tool(),e=watchedEntity(),graph=$('brainGraph');if(!t||!e||!graph)return;const nodes=(e.activeNodes??[]).map(id=>t.brain.find(n=>n.id===id)).filter(Boolean),n=[...nodes].reverse().find(n=>n.type==='action'&&e.nodeStatus?.[n.id]==='running')??[...nodes].reverse().find(n=>n.type==='action')??nodes[0];if(!n)return;const rect=graph.getBoundingClientRect(),x=n.x*GRAPH_X,y=n.y*GRAPH_Y,left=graph.scrollLeft??0,top=graph.scrollTop??0;let nx=left,ny=top;if(force||x<left+15||x+GRAPH_NODE_WIDTH>left+rect.width-15)nx=Math.max(0,x-(rect.width-GRAPH_NODE_WIDTH)/2);if(force||y<top+15||y+195>top+rect.height-15)ny=Math.max(0,y-(rect.height-195)/2);graph.scrollTo({left:nx,top:ny,behavior:'auto'});}
window.addEventListener('pointermove',e=>{if(!graphDrag)return;graphDrag.node.x=Math.max(10,Math.min(4000,(e.clientX-graphDrag.x)/GRAPH_X));graphDrag.node.y=Math.max(10,Math.min(4000,(e.clientY-graphDrag.y)/GRAPH_Y));graphDrag.el.style.left=graphDrag.node.x*GRAPH_X+'px';graphDrag.el.style.top=graphDrag.node.y*GRAPH_Y+'px';requestBrainWires();});window.addEventListener('pointerup',()=>{if(graphDrag){graphDrag=null;changed();requestBrainWires();}});
function editBrainNode(owner,id){setRunning(false);const t=world.tools.find(t=>t.id===owner),n=structuredClone(t.brain.find(n=>n.id===id)),children=t.edges.filter(([a])=>a===id).map(([,b])=>t.brain.find(n=>n.id===b));const actions=[['idle','Do nothing / succeed'],['chooseTarget','Choose a point → store in memory'],['moveTarget','Move to a stored location'],['wait','Wait a chosen duration'],['rememberTarget','Record a stored location in history'],['clearTarget','Clear a stored location'],['clearHistory','Clear a location history'],['acknowledge','Acknowledge the message stored with a location'],['rule','Apply an interaction rule'],['interact','Interact with a nearby object'],['wander','Take a random adjacent step'],['zone','Move into a zone (any-cell / legacy point mode)']];if(['patrol','directive','seek'].includes(n.action))actions.push([n.action,'Legacy bundled '+n.action+' (existing node)']);
modal('Configure '+n.type+' node',`<div class="form-grid"><label class="field">Label<input id="nodeLabel" maxlength="80" value="${esc(n.label)}"></label><label class="field">Node type<select id="nodeType">${options((id==='root'?[['selector','Selector'],['sequence','Sequence'],['utility','Utility selector']]:[['selector','Selector'],['sequence','Sequence'],['utility','Utility selector'],['condition','Condition'],['action','Action']]),n.type)}</select></label><label class="field">Graph X<input id="nodePosX" type="number" min="0" max="4000" value="${n.x}"></label><label class="field">Graph Y<input id="nodePosY" type="number" min="0" max="4000" value="${n.y}"></label></div>
<div class="form-section">SEQUENCE EXECUTION</div><label class="field">Sequence mode<select id="nodeSequenceMode">${options([['reactive','Recheck from the first child each tick'],['memory','Continue at the running child; advance after success']],n.sequenceMode??'reactive')}</select></label><label class="field"><span><input id="nodeResetInterrupted" type="checkbox" ${n.resetOnInterrupt!==false?'checked':''}> Restart a sequence / wait after another branch interrupts it</span></label>
<div class="form-section">CONDITION</div><div class="form-grid"><label class="field">Read<select id="nodeCondition">${options([['stat','An assigned stat'],['tag','A tag'],['zone','Zone membership'],['message','A director message'],['target','A stored location']],n.condition)}</select></label><label class="field">Stat<select id="nodeStat">${selectOptions(ownedStats(t),n.stat)}</select></label><label class="field">Comparison<select id="nodeOp">${options([['<','<'],['<=','≤'],['>','>'],['>=','≥'],['==','='],['!=','≠']],n.op)}</select></label><label class="field">Threshold<input id="nodeThreshold" type="number" value="${n.threshold}"></label><label class="field">Tag<select id="nodeTag">${selectOptions(world.tagDefs,n.tag)}</select></label><label class="field">Tag check<select id="nodeTagMode">${options([['present','Present'],['absent','Absent']],n.tagMode)}</select></label><label class="field">Zone<select id="nodeZone">${selectOptions(world.zones,n.zoneId)}</select></label><label class="field">Zone check<select id="nodeZoneMode">${options([['inside','Inside'],['outside','Outside']],n.zoneMode)}</select></label><label class="field">Message name<input id="nodeMessageKey" maxlength="60" value="${esc(n.messageKey)}"></label><label class="field">Message data name<input id="nodeMessageField" maxlength="40" value="${esc(n.messageField??'')}"></label><label class="field">Location data name<input id="nodeMessageTargetField" maxlength="40" value="${esc(n.messageTargetField??'zone')}"></label><label class="field">Compare text<input id="nodeMessageText" maxlength="500" value="${esc(n.messageText??'')}"></label><label class="field"><span><input id="nodeMessageBoolean" type="checkbox" ${n.messageBoolean!==false?'checked':''}> Compare with true</span></label><label class="field">Message check<select id="nodeMessageCheck">${options([['present','Present'],['absent','Absent'],['value','Compare number data'],['text','Compare text data'],['boolean','Compare boolean data'],['fieldPresent','Data exists'],['fieldAbsent','Data absent']],n.messageCheck??'present')}</select></label><label class="field">Stored location check<select id="nodeTargetCheck">${options([['present','Exists'],['absent','Does not exist'],['valid','Is usable / message is active'],['reached','Creature is at this location']],n.targetCheck??'present')}</select></label></div>
<div class="form-section">ACTION</div><div class="form-grid"><label class="field">Action<select id="nodeAction">${options(actions,n.action)}</select></label><label class="field">Object type to interact with<select id="nodeTarget">${selectOptions(world.tools,n.targetTool)}</select></label><label class="field">Interaction rule<select id="nodeRule">${selectOptions(t.rules.filter(r=>r.trigger==='behavior'),n.ruleId)}</select></label></div><label class="field"><span><input id="nodeRuleNoop" type="checkbox" ${n.ruleNoopSuccess?'checked':''}> A rule making no change still succeeds</span></label>
<div class="form-section">LOCATION MEMORY</div><div class="form-grid"><label class="field">Location memory key<input id="nodeSlot" maxlength="40" value="${esc(n.slot??'destination')}"></label><label class="field">Location history key<input id="nodeHistoryKey" maxlength="40" value="${esc(n.historyKey??'visited')}"></label><label class="field">Keep this many history entries<input id="nodeHistoryLimit" type="number" min="1" max="30" value="${n.historyLimit??10}"></label><label class="field">Require source message to stay active<input id="nodeRequireLive" type="checkbox" ${n.requireLiveInput!==false?'checked':''}></label></div>
<div id="pointSelectionSettings"><div class="form-section">CHOOSE A POINT (DOES NOT MOVE)</div><div class="form-grid"><label class="field">Location source<select id="nodeSelectionSource">${options([['zones','Selected zones'],['current','Any zone the creature currently occupies'],['message','Zone, area, or position data from a message'],['radius','Within a radius of a location']],n.selectionSource??'zones')}</select></label><label class="field">Zone relation to the creature<select id="nodeZoneRelation">${options([['any','Inside or outside a zone'],['inside','Only zones it is inside'],['outside','Only zones it is outside']],n.zoneRelation??'any')}</select></label><div class="field wide">Candidate zones<div class="assignment-list">${world.zones.map(z=>`<label><input type="checkbox" data-selection-zone="${z.id}" ${n.selectionZones?.includes(z.id)?'checked':''}> ${esc(z.name)}</label>`).join('')}</div></div><label class="field">Origin location key (blank = self)<input id="nodeOriginSlot" maxlength="40" value="${esc(n.originSlot??'')}"></label><label class="field">Radius in cells<input id="nodeRadius" type="number" min="0" max="30" value="${n.radius??4}"></label><label class="field">Prefer minimum distance from self<input id="nodeMinTravel" type="number" min="0" max="100" value="${n.minTravel??0}"></label><label class="field">When this node runs<select id="nodeChoosePolicy">${options([['replace','Choose a new point'],['keep','Keep an existing usable point; choose only if empty']],n.choosePolicy??'replace')}</select></label><label class="field">Avoid recent history entries<input id="nodeAvoidRecent" type="number" min="0" max="10" value="${n.avoidRecent??0}"></label><label class="field">Match history by<select id="nodeHistoryMode">${options([['zone','Zone'],['point','Exact cell']],n.historyMode??'zone')}</select></label><label class="field"><span><input id="nodeHistoryFallback" type="checkbox" ${n.historyFallback!==false?'checked':''}> Allow recent candidates if no alternative is reachable</span></label></div></div>
<div class="form-section">MOVEMENT AND WAITING</div><div class="form-grid"><label class="field">Route<select id="nodeRouteStyle">${options([['shortest','Shortest'],['varied','Varied, stable for this chosen point']],n.routeStyle??'shortest')}</select></label><label class="field"><span><input id="nodeDiagonal" type="checkbox" ${n.diagonal?'checked':''}> Allow diagonals without cutting blocked corners</span></label><label class="field">Minimum wait ticks<input id="nodeWaitMin" type="number" min="0" max="1000" value="${n.waitMin??2}"></label><label class="field">Maximum wait ticks<input id="nodeWaitMax" type="number" min="0" max="1000" value="${n.waitMax??6}"></label><label class="field">Adjacent-step radius (0 = unbounded)<input id="nodeWanderRadius" type="number" min="0" max="30" value="${n.wanderRadius??0}"></label></div>
<div class="form-section">UTILITY SCORING AND COMMITMENT</div><div class="form-grid"><label class="field">Stat<select id="nodeScoreStat">${selectOptions(ownedStats(t),n.scoreStat,'Constant weight')}</select></label><label class="field">Prefer<select id="nodeDirection">${options([['low','Low values'],['high','High values']],n.direction)}</select></label><label class="field">Weight<input id="nodeWeight" type="number" min="0" max="10" step="0.1" value="${n.weight}"></label><label class="field">Message score source<select id="nodeMessageScore">${options([['field','Named number data'],['weight','Legacy priority data'],['value','Legacy value data']],n.messageScore??'weight')}</select></label><label class="field">Message score multiplier<input id="nodeMessageScale" type="number" min="0" max="100" step="0.1" value="${n.messageScale??1}"></label><label class="field">Zone modifier<select id="nodeScoreZone">${selectOptions(world.zones,n.scoreZone,'None')}</select></label><label class="field">Apply when<select id="nodeScoreZoneMode">${options([['inside','Inside'],['outside','Outside']],n.scoreZoneMode)}</select></label><label class="field">Zone multiplier<input id="nodeZoneMultiplier" type="number" min="0" max="10" step="0.1" value="${n.zoneMultiplier??1}"></label><label class="field"><span><input id="nodeCommitRunning" type="checkbox" ${n.commitRunning?'checked':''}> Utility selector continues its running child</span></label><label class="field">Maximum commitment ticks<input id="nodeCommitTicks" type="number" min="1" max="10000" value="${n.commitTicks??120}"></label><label class="field">Stronger interruption margin<input id="nodeInterruptMargin" type="number" min="0" max="100" step="0.1" value="${n.interruptMargin??1}"></label></div>
<details class="${['patrol','directive','zone','seek'].includes(n.action)?'':'hidden'}" ${['patrol','directive','zone','seek'].includes(n.action)?'open':''}><summary>Older bundled-action settings (compatibility)</summary><div class="form-grid"><label class="field">Legacy zone arrival<select id="nodeGoalMode">${options([['area','Any cell'],['point','Chosen point']],n.goalMode??'area')}</select></label><label class="field"><span><input id="nodeFinishGoal" type="checkbox" ${n.finishGoal?'checked':''}> Finish accepted legacy input goal</span></label><label class="field"><span><input id="nodeConsumeMessage" type="checkbox" ${n.consumeMessage!==false?'checked':''}> Consume legacy input on arrival</span></label><div class="field wide">Legacy patrol zones<div class="assignment-list">${world.zones.map(z=>`<label><input type="checkbox" data-patrol-zone="${z.id}" ${n.patrolZones?.includes(z.id)?'checked':''}> ${esc(z.name)}</label>`).join('')}</div></div><label class="field">Legacy pause min<input id="nodePauseMin" type="number" value="${n.pauseMin??2}"></label><label class="field">Legacy pause max<input id="nodePauseMax" type="number" value="${n.pauseMax??6}"></label></div></details>
<div class="form-section">CHILD ORDER</div>${children.map((child,i)=>`<div class="mini-row"><span>${i+1}. ${esc(child.label)}</span><button data-order-up="${child.id}">↑</button><button data-order-down="${child.id}">↓</button></div>`).join('')}<div id="formError" class="form-error"></div><div class="dialog-actions">${id!=='root'?'<button id="deleteBrainNode" class="danger">Delete node</button>':''}<button id="cancelNode">Cancel</button><button class="primary" id="saveBrainNode">Save node</button></div>`);
function fields(){const type=$('nodeType').value,condition=$('nodeCondition').value,action=$('nodeAction').value;$('pointSelectionSettings').classList.toggle('hidden',type!=='action'||action!=='chooseTarget');for(const id of ['nodeSequenceMode'])$(id).disabled=type!=='sequence';for(const id of ['nodeCommitRunning','nodeCommitTicks','nodeInterruptMargin'])$(id).disabled=type!=='utility';$('nodeAction').disabled=type!=='action';$('nodeMessageCheck').disabled=type!=='condition'||condition!=='message';$('nodeTargetCheck').disabled=type!=='condition'||condition!=='target';$('nodeZone').disabled=!((type==='condition'&&condition==='zone')||(type==='action'&&action==='zone'));$('nodeZoneMode').disabled=type!=='condition'||condition!=='zone';$('nodeStat').disabled=type!=='condition'||condition!=='stat';for(const id of ['nodeTag','nodeTagMode'])$(id).disabled=type!=='condition'||condition!=='tag';for(const id of ['nodeOp','nodeThreshold'])$(id).disabled=type!=='condition'||!(condition==='stat'||condition==='message'&&['value','number','text'].includes($('nodeMessageCheck').value));}fields();for(const id of ['nodeType','nodeCondition','nodeAction','nodeMessageCheck','nodeSelectionSource'])$(id).onchange=fields;$('cancelNode').onclick=()=>$('dialog').close();
$('saveBrainNode').onclick=()=>{const map={label:'nodeLabel',type:'nodeType',condition:'nodeCondition',stat:'nodeStat',op:'nodeOp',tag:'nodeTag',tagMode:'nodeTagMode',zoneId:'nodeZone',zoneMode:'nodeZoneMode',messageKey:'nodeMessageKey',messageField:'nodeMessageField',messageTargetField:'nodeMessageTargetField',messageText:'nodeMessageText',messageCheck:'nodeMessageCheck',targetCheck:'nodeTargetCheck',action:'nodeAction',targetTool:'nodeTarget',ruleId:'nodeRule',slot:'nodeSlot',originSlot:'nodeOriginSlot',historyKey:'nodeHistoryKey',selectionSource:'nodeSelectionSource',zoneRelation:'nodeZoneRelation',choosePolicy:'nodeChoosePolicy',historyMode:'nodeHistoryMode',sequenceMode:'nodeSequenceMode',routeStyle:'nodeRouteStyle',scoreStat:'nodeScoreStat',direction:'nodeDirection',messageScore:'nodeMessageScore',scoreZone:'nodeScoreZone',scoreZoneMode:'nodeScoreZoneMode',goalMode:'nodeGoalMode'};for(const [key,id]of Object.entries(map))n[key]=$(id).value.trim();for(const [key,id]of Object.entries({x:'nodePosX',y:'nodePosY',threshold:'nodeThreshold',historyLimit:'nodeHistoryLimit',radius:'nodeRadius',minTravel:'nodeMinTravel',avoidRecent:'nodeAvoidRecent',waitMin:'nodeWaitMin',waitMax:'nodeWaitMax',wanderRadius:'nodeWanderRadius',weight:'nodeWeight',messageScale:'nodeMessageScale',zoneMultiplier:'nodeZoneMultiplier',commitTicks:'nodeCommitTicks',interruptMargin:'nodeInterruptMargin',pauseMin:'nodePauseMin',pauseMax:'nodePauseMax'}))n[key]=num(id);for(const [key,id]of Object.entries({messageBoolean:'nodeMessageBoolean',resetOnInterrupt:'nodeResetInterrupted',ruleNoopSuccess:'nodeRuleNoop',requireLiveInput:'nodeRequireLive',historyFallback:'nodeHistoryFallback',diagonal:'nodeDiagonal',commitRunning:'nodeCommitRunning',finishGoal:'nodeFinishGoal',consumeMessage:'nodeConsumeMessage'}))n[key]=$(id).checked;n.selectionZones=[...$('dialogBody').querySelectorAll('[data-selection-zone]:checked')].map(el=>el.dataset.selectionZone);n.patrolZones=[...$('dialogBody').querySelectorAll('[data-patrol-zone]:checked')].map(el=>el.dataset.patrolZone);
if(!n.label)return error('Give this node a label.');if(n.type==='condition'&&n.condition==='stat'&&!n.stat)return error('Choose the condition stat.');if(n.type==='condition'&&n.condition==='tag'&&!n.tag)return error('Choose a condition tag.');if(n.action==='chooseTarget'&&n.selectionSource==='zones'&&!n.selectionZones.length)return error('Choose candidate zones.');if(((n.type==='condition'&&n.condition==='message')||n.action==='directive'||n.action==='chooseTarget'&&n.selectionSource==='message')&&!n.messageKey)return error('Name the message.');if(n.action==='rule'&&!n.ruleId)return error('Choose a behavior-only rule.');const candidate=structuredClone(world),ct=candidate.tools.find(t=>t.id===owner);ct.brain[ct.brain.findIndex(v=>v.id===id)]=n;if(['action','condition'].includes(n.type))ct.edges=ct.edges.filter(([a])=>a!==id);if(!validWorld(candidate))return error('Check memory names, selected references and numeric ranges. Memory names start with a letter and use letters, numbers, underscores or hyphens; wait maximum must be at least minimum.');checkpoint();t.brain=ct.brain;t.edges=ct.edges;for(const e of world.entities.filter(e=>e.toolId===owner)){delete e.navigation;delete e.acceptedMessage;delete e.utilityMemory;delete e.sequenceMemory;delete e.waitTimers;}changed();renderGraph();renderInspector();$('dialog').close();};if(id!=='root')$('deleteBrainNode').onclick=()=>{checkpoint();resetGraphExecution(t.id);t.brain=t.brain.filter(n=>n.id!==id);t.edges=t.edges.filter(([a,b])=>a!==id&&b!==id);changed();renderGraph();$('dialog').close();};function reorder(child,direction){const indices=t.edges.map((edge,i)=>({edge,i})).filter(x=>x.edge[0]===id),i=indices.findIndex(x=>x.edge[1]===child),other=i+direction;if(other<0||other>=indices.length)return;checkpoint();resetGraphExecution(t.id);const a=indices[i].i,b=indices[other].i;[t.edges[a],t.edges[b]]=[t.edges[b],t.edges[a]];changed();renderGraph();editBrainNode(owner,id);}$('dialogBody').querySelectorAll('[data-order-up]').forEach(b=>b.onclick=()=>reorder(b.dataset.orderUp,-1));$('dialogBody').querySelectorAll('[data-order-down]').forEach(b=>b.onclick=()=>reorder(b.dataset.orderDown,1));}
function renderHistoryView(){const h=world.historySettings;for(const [id,value]of [['historySeed',h.seed],['historyYears',h.years],['historyCount',h.count],['historyNames',h.names]])if(document.activeElement!==$(id))$(id).value=value;$('historyFactions').innerHTML=world.factions.map(f=>`<div class="history-faction"><strong>${esc(f.name)}</strong><p>${esc(f.leader)}<br>${f.population} inhabitants<br>${esc(f.faith)} · ${f.war===null?'At peace':'In conflict'}</p></div>`).join('');$('historyEntries').innerHTML=world.history.length?world.history.slice(0,300).map(e=>`<div class="history-entry"><time>Year ${e.year}</time><div><small>${esc(e.type)}</small><p>${esc(e.text)}</p></div></div>`).join(''):empty('Empty');}
$('newTag').onclick=()=>editTag();$('generateHistory').onclick=()=>{const settings={seed:$('historySeed').value.trim()||'world-1',years:Math.max(1,Math.min(500,Math.round(num('historyYears',100)))),count:Math.max(1,Math.min(10,Math.round(num('historyCount',3)))),names:$('historyNames').value.slice(0,1000)};setRunning(false);checkpoint();const result=generateHistory(settings.seed,settings.years,settings.count,settings.names.split(String.fromCharCode(10)).map(n=>n.trim().slice(0,60)).filter(Boolean));world.historySettings=settings;world.history=result.history;world.factions=result.factions;world.year=settings.years;baseline=null;changed();renderHistoryView();toast('History generated. Board and object type definitions preserved.');};
window.addEventListener('keydown',e=>{if(e.key==='Escape'&&treeVisible()){connecting=null;renderGraph();}});

$('help').onclick=()=>modal('Your object types, stats, tags, and behavior trees', '<p><b>Object types:</b> Create your own object types, enable collision or movement, and use a basic color or uploaded PNG/JPEG. No preset artwork or survival stats.</p><p><b>Stats are opt-in:</b> A library definition changes nothing by itself. Open an object type and select only the stats it should own. This updates that object type’s existing instances without changing other object types. Effects name exactly one stat and target. A missing target stat is skipped, never created.</p><p><b>Defined tags:</b> Each tag has a name and written purpose. Assign tags selectively to object types or individual instances. Choose them in Self/Other rule filters or tree conditions; add/remove them with rule effects. Tag definitions show the rules and tree nodes that reference them. Descriptions document meaning; explicit rules implement it.</p><p><b>Behavior trees:</b> Choose an object type in Behavior tree / AI. Add selector, sequence, utility, condition, or action nodes. Connect outputs to inputs, drag to arrange, click wires to disconnect, and edit child order. Enable the graph to run it. Disable it to use the existing standalone utility decisions. Utility selectors score their children from attached stats or constant weights. The graph shows success, failure, and running results.</p><p><b>Custom actions:</b> Define a rule with the behavior-only trigger, then call it from an action node. Tick, contact, and manual interaction rules remain available alongside the graph.</p><p><b>World history generator:</b> Seeded generation records founders, succession, conflicts, peace, and changing beliefs. Set your own faction names. Generation does not replace the board or its definitions. Runtime time advances one year per 240 ticks. History is a small separate simulation.</p><p><b>Board and saves:</b> Draw, select, erase, pan, zoom, undo/redo, manually interact, and inspect events. Save/load and JSON import/export include artwork, selected stats, tag purposes, graphs, utility decisions, and history. Older v0.2 projects are upgraded on load while preserving their existing values and assignments.</p>');

function renderCreatures(){const creatures=world.tools.filter(t=>t.kind==='creature');$('creatureCount').textContent=creatures.length;$('creatureCards').innerHTML=creatures.length?creatures.map(t=>{const branches=t.brain.filter(n=>n.type==='utility').reduce((count,n)=>count+t.edges.filter(([a])=>a===n.id).length,0);return `<article class="creature-card"><div class="creature-card-title"><h3>${esc(t.name)}</h3><span class="tag">${t.spawn.enabled?'Automatic spawning on':'Automatic spawning off'}</span></div><div class="creature-summary"><div><p>${ownedStats(t).map(s=>`${esc(s.name)} <span class="compact">${t.defaults[s.id]??s.start}</span>`).join(' · ')||'None — choose only what it needs'}</p></div><div><p>${t.tags.map(id=>`<span title="${esc(tagDef(id)?.description)}">${esc(tagDef(id)?.name)}</span>`).join(' · ')||'None assigned'}</p></div><div><p>${t.brain.length} nodes · ${branches} scored branches · ${t.brainEnabled?'Enabled':'Disabled'}</p></div><div><p>${world.entities.filter(e=>e.toolId===t.id).length} placed instances</p></div></div><div class="action-row"><button data-creature-config="${t.id}">Stats & tags</button><button data-creature-brain="${t.id}">Behavior tree</button><button data-creature-utility="${t.id}">＋ Utility branch</button><button data-creature-draw="${t.id}">Place on board</button><button data-creature-spawn="${t.id}">Spawning settings</button></div></article>`;}).join(''):empty('Empty');for(const [key,handler]of [['config',id=>editTool(id)],['brain',id=>{toolId=id;entityId=null;switchView('behavior');}],['utility',id=>editCreatureUtility(id)],['draw',id=>{toolId=id;entityId=null;switchView('board');setMode('draw');renderTools();renderInspector();}],['spawn',id=>editCreatureSpawn(id)]])$('creatureCards').querySelectorAll('[data-creature-'+key+']').forEach(b=>b.onclick=()=>handler(b.dataset['creature'+key[0].toUpperCase()+key.slice(1)]));}
function editCreatureSpawn(owner){setRunning(false);const t=world.tools.find(t=>t.id===owner);if(!t||t.kind!=='creature')return;const settings=t.spawn;modal('Optional independent spawning',`<p><b>${esc(t.name)}</b> can always be placed manually using its object palette. Independent spawning is optional and is off for every newly created creature.</p><div class="checks"><label><input id="creatureSpawnEnabled" type="checkbox" ${settings.enabled?'checked':''}> Enable automatic spawning during simulation</label></div><div class="form-grid"><label class="field">One new instance every N ticks<input id="creatureSpawnInterval" type="number" min="1" max="100000" value="${settings.interval}"></label><label class="field">Maximum instances of this creature<input id="creatureSpawnLimit" type="number" min="1" max="500" value="${settings.limit}"></label><label class="field">Preferred X<input id="creatureSpawnX" type="number" min="0" max="${WIDTH-1}" value="${settings.x}"></label><label class="field">Preferred Y<input id="creatureSpawnY" type="number" min="0" max="${HEIGHT-1}" value="${settings.y}"></label></div><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="cancelCreatureSpawn">Cancel</button><button class="primary" id="saveCreatureSpawn">Save spawning settings</button></div>`);$('cancelCreatureSpawn').onclick=()=>$('dialog').close();$('saveCreatureSpawn').onclick=()=>{const spawn={enabled:$('creatureSpawnEnabled').checked,interval:num('creatureSpawnInterval'),limit:num('creatureSpawnLimit'),x:num('creatureSpawnX'),y:num('creatureSpawnY')};if(![spawn.interval,spawn.limit,spawn.x,spawn.y].every(Number.isInteger)||spawn.interval<1||spawn.interval>100000||spawn.limit<1||spawn.limit>500||spawn.x<0||spawn.x>=WIDTH||spawn.y<0||spawn.y>=HEIGHT)return error('Use valid whole numbers within the displayed ranges.');checkpoint();t.spawn=spawn;changed();refresh();$('dialog').close();toast('Independent spawning '+(spawn.enabled?'enabled.':'off. Manual placement remains available.'));};}
function editCreatureUtility(owner){setRunning(false);const t=world.tools.find(t=>t.id===owner);if(!t)return;if(!ownedStats(t).length){toast('Assign a stat to this creature first; utility scores use only its own stats.');editTool(owner);return;}const parents=t.brain.filter(n=>n.type==='utility'),initial=parents.find(n=>n.id==='root')?.id??parents[0]?.id??'';modal('Add a scored behavior branch',`<div class="form-grid"><label class="field">Branch name<input id="creatureBranchName" maxlength="80" placeholder="Your own decision name"></label><label class="field">Parent utility selector<select id="creatureBranchParent">${selectOptions(parents.map(n=>({id:n.id,name:n.label})),initial,'Create a utility selector under the root')}</select></label><label class="field">Score from this creature's stat<select id="creatureBranchStat">${selectOptions(ownedStats(t),ownedStats(t)[0].id)}</select></label><label class="field">Priority increases when<select id="creatureBranchDirection"><option value="low">The stat is low</option><option value="high">The stat is high</option></select></label><label class="field">Weight<input id="creatureBranchWeight" type="number" min="0" max="10" step="0.1" value="1"></label><label class="field">Required tag (optional)<select id="creatureBranchTag">${selectOptions(world.tagDefs,'','No tag gate')}</select></label><label class="field">Action<select id="creatureBranchAction"><option value="idle">Idle</option><option value="wander">Move around</option><option value="interact">Interact with nearby target</option><option value="rule">Run a behavior-only rule</option><option value="zone">Go to a painted zone</option></select></label><label class="field">Target object type<select id="creatureBranchTarget">${selectOptions(world.tools,'')}</select></label><label class="field">Painted zone<select id="creatureBranchZone">${selectOptions(world.zones,'')}</select></label><label class="field wide">Behavior-only rule<select id="creatureBranchRule">${selectOptions(t.rules.filter(r=>r.trigger==='behavior'),'')}</select></label></div><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="cancelCreatureBranch">Cancel</button><button class="primary" id="saveCreatureBranch">Add to behavior tree</button></div>`);function fields(){const action=$('creatureBranchAction').value;$('creatureBranchTarget').disabled=!['seek','interact'].includes(action);$('creatureBranchRule').disabled=action!=='rule';$('creatureBranchZone').disabled=action!=='zone';}fields();$('creatureBranchAction').onchange=fields;$('cancelCreatureBranch').onclick=()=>$('dialog').close();$('saveCreatureBranch').onclick=()=>{const config={name:$('creatureBranchName').value.trim(),parentId:$('creatureBranchParent').value,stat:$('creatureBranchStat').value,direction:$('creatureBranchDirection').value,weight:num('creatureBranchWeight'),tag:$('creatureBranchTag').value,action:$('creatureBranchAction').value,targetTool:$('creatureBranchTarget').value,ruleId:$('creatureBranchRule').value,zoneId:$('creatureBranchZone').value};try{const candidate=structuredClone(t);addUtilityBranch(world,candidate,config);checkpoint();world.tools[world.tools.findIndex(tool=>tool.id===owner)]=candidate;toolId=owner;changed();$('dialog').close();switchView('behavior');refresh();toast('Scored branch added to this creature’s behavior tree.');}catch(e){error(e.message);}};}
function convertCreature(){setRunning(false);const candidates=world.tools.filter(t=>t.kind==='object');if(!candidates.length)return toast('There are no existing object types to use. Create a creature instead.');modal('Convert an object type to a creature',`<label class="field">Object type<select id="convertCreatureTool">${selectOptions(candidates,'')}</select></label><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="cancelConvertCreature">Cancel</button><button class="primary" id="saveConvertCreature">Use as creature</button></div>`);$('cancelConvertCreature').onclick=()=>$('dialog').close();$('saveConvertCreature').onclick=()=>{const t=world.tools.find(t=>t.id===$('convertCreatureTool').value);if(!t)return error('Choose an object type.');checkpoint();t.kind='creature';t.spawn.enabled=false;toolId=t.id;changed();refresh();$('dialog').close();editTool(t.id);};}
function createCreatureStat(owner){setRunning(false);const t=world.tools.find(t=>t.id===owner);modal('Create and assign a creature stat',`<div class="form-grid"><label class="field wide">Name<input id="creatureStatName" maxlength="60"></label><label class="field">Minimum<input id="creatureStatMin" type="number" step="any" value="0"></label><label class="field">Maximum<input id="creatureStatMax" type="number" step="any" value="100"></label><label class="field">Starting value<input id="creatureStatStart" type="number" step="any" value="0"></label></div><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="cancelCreatureStat">Back to creature</button><button class="primary" id="saveCreatureStat">Create & assign to this creature</button></div>`);$('cancelCreatureStat').onclick=()=>editTool(owner);$('saveCreatureStat').onclick=()=>{const name=$('creatureStatName').value.trim(),min=num('creatureStatMin'),max=num('creatureStatMax'),start=num('creatureStatStart');if(!name||max<=min||start<min||start>max)return error('Enter a name and a valid range with a starting value inside it.');if(world.stats.length>=50)return error('Prototype limit: 50 stat definitions.');if(world.stats.some(s=>s.name.toLowerCase()===name.toLowerCase()))return error('That stat already exists. Assign its existing definition in the creature editor.');checkpoint();const stat=addStat(world,name,min,max,start);setToolStats(world,t,[...t.statIds,stat.id]);changed();refresh();editTool(owner);};}
$('createCreature').onclick=$('libraryNewCreature').onclick=()=>editTool(null,'creature');$('convertCreature').onclick=convertCreature;

const creatureBaseHelp=$('help').onclick;$('help').onclick=()=>{creatureBaseHelp();$('dialogBody').insertAdjacentHTML('afterbegin','<p><b>Creatures:</b> Open Creatures to create a definition, assign only its own stats and tags, then add scored behavior branches. These branches are placed directly inside the behavior tree, so utility scoring and conditions decide together. No new appearance system is required; existing object display settings are optional. Use the object palette to place instances manually. Independent spawning is off by default and can be enabled with an interval, origin, and population limit.</p>');};
function setMode(m){baseSetMode(m);if(m==='zone'||m==='zoneErase'){$('board').style.cursor='crosshair';const z=world.zones.find(z=>z.id===zoneId);$('boardCaption').textContent=z?`${m==='zone'?'Paint':'Erase'} ${z.name} · areas never create collision`:'Choose or create a zone';}analytics?.record('board_mode_changed',{panel:'board',context:{mode:m==='zone'?'zone-add':m==='zoneErase'?'zone-remove':m}});}
function renderZones(){if(!world.zones.some(z=>z.id===zoneId))zoneId=world.zones[0]?.id??null;$('zoneCount').textContent=world.zones.length;$('zoneBrushes').innerHTML=world.zones.map(z=>`<button class="zone-brush ${z.id===zoneId&&mode==='zone'?'active':''}" data-zone-brush="${z.id}"><i style="border-color:${z.color};background:${z.color}25"></i><span>${esc(z.name)}</span><small>${zoneCells(world,z).length}</small></button>`).join('')||'';$('zoneBrushes').querySelectorAll('button').forEach(b=>b.onclick=()=>{zoneId=b.dataset.zoneBrush;switchView('board');setMode('zone');renderZones();draw();});$('zoneCards').innerHTML=world.zones.length?world.zones.map(z=>{const stat=world.stats.find(s=>s.id===z.stat),effect=z.effect==='stat'?`${z.amount>=0?'+':''}${z.amount} ${stat?.name??'selected stat'}`:z.effect==='none'?'Membership only':`${z.effect==='tag'?'Add':'Remove'} ${tagDef(z.tag)?.name??'tag'}`;const refs=world.tools.reduce((count,t)=>count+t.brain.filter(n=>n.zoneId===z.id||n.scoreZone===z.id).length+t.decisions.filter(d=>d.zoneId===z.id||d.scoreZone===z.id).length,0);return `<article class="zone-card"><div class="creature-card-title"><h3>${esc(z.name)}</h3><span class="tag">${z.enabled?'Enabled':'Disabled'} · no collision</span></div>${z.description?`<p>${esc(z.description)}</p>`:''}<div class="zone-meta"><span>${z.placement==='attached'?'Attached · '+zoneCells(world,z).length+' current cells':z.cells.length+' painted cells'}</span><span>${esc(effect)} · ${z.trigger==='enter'?'on entry':'each tick'}</span><span>${refs} AI references</span></div><div class="action-row"><button data-zone-edit="${z.id}">Configure zone</button><button data-zone-paint="${z.id}">Paint zone</button><button data-zone-erase="${z.id}">Erase zone</button></div></article>`;}).join(''):empty('Empty');for(const [key,handler]of [['edit',id=>editZone(id)],['paint',id=>{zoneId=id;switchView('board');setMode('zone');renderZones();}],['erase',id=>{zoneId=id;switchView('board');setMode('zoneErase');renderZones();}]])$('zoneCards').querySelectorAll('[data-zone-'+key+']').forEach(b=>b.onclick=()=>handler(b.dataset['zone'+key[0].toUpperCase()+key.slice(1)]));}
function zoneRenderGeometry(z){const geometry=zoneCells(world,z),cached=zoneRenderCache.get(z);if(cached?.projectRevision===projectRevision&&cached.geometry===geometry)return cached;const cells=new Set(geometry),segments=[];let minX=WIDTH,minY=HEIGHT;for(const cell of geometry){const x=cell%WIDTH,y=Math.floor(cell/WIDTH);minX=Math.min(minX,x);minY=Math.min(minY,y);if(x===0||!cells.has(cell-1))segments.push([x,y,x,y+1]);if(x===WIDTH-1||!cells.has(cell+1))segments.push([x+1,y,x+1,y+1]);if(y===0||!cells.has(cell-WIDTH))segments.push([x,y,x+1,y]);if(y===HEIGHT-1||!cells.has(cell+WIDTH))segments.push([x,y+1,x+1,y+1]);}const result={projectRevision,geometry,segments,minX,minY};zoneRenderCache.set(z,result);return result;}
function drawZones(ctx,ox,oy,size){ctx.save();for(const z of world.zones){const {geometry,segments,minX,minY}=zoneRenderGeometry(z);if(!z.enabled||!geometry.length)continue;ctx.fillStyle=z.color;ctx.globalAlpha=z.id===zoneId&&['zone','zoneErase'].includes(mode)?.27:.13;for(const cell of geometry){const x=cell%WIDTH,y=Math.floor(cell/WIDTH);ctx.fillRect(ox+x*size,oy+y*size,size,size);}ctx.globalAlpha=.55;ctx.strokeStyle=z.color;ctx.lineWidth=.65;ctx.beginPath();for(const [x1,y1,x2,y2]of segments){ctx.moveTo(ox+x1*size,oy+y1*size);ctx.lineTo(ox+x2*size,oy+y2*size);}ctx.stroke();ctx.globalAlpha=1;ctx.font='14px Arial, sans-serif';const label=z.name,width=ctx.measureText(label).width+12,x=ox+minX*size+5,y=oy+minY*size+5;ctx.fillStyle='#1c2530e8';ctx.fillRect(x,y,width,26);ctx.fillStyle='#e1e8f0';ctx.fillText(label,x+6,y+18);}ctx.restore();}
function editZone(id){setRunning(false);const old=world.zones.find(z=>z.id===id),z=structuredClone(old??makeZone('Zone '+(world.zones.length+1)));modal(old?'Configure zone':'Create zone',`<div class="form-grid"><div class="form-section">ZONE PLACEMENT</div><div class="form-grid"><label class="field">Placement<select id="zonePlacement">${options([['painted','Painted on the map'],['attached','Relative to objects']],z.placement??'painted')}</select></label><label class="field">Anchor selection<select id="zoneAnchorKind">${options([['entity','One placed object'],['tool','All objects of one type'],['tag','All objects with a tag']],z.anchorKind??'entity')}</select></label><label class="field">Placed object<select id="zoneAnchorEntity">${options([['','Choose an object'],...world.entities.map(e=>[e.id,(world.tools.find(t=>t.id===e.toolId)?.name??'Object')+' at '+e.x+', '+e.y])],z.anchorEntity??'')}</select></label><label class="field">Anchor object type<select id="zoneAnchorTool">${selectOptions(world.tools,z.anchorTool??'','Choose an object type')}</select></label><label class="field">Anchor tag<select id="zoneAnchorTag">${selectOptions(world.tagDefs,z.anchorTag??'','Choose a tag')}</select></label><label class="field">Shape<select id="zoneShape">${options([['circle','Circle / ring'],['square','Square / hollow square']],z.shape??'circle')}</select></label><label class="field">Inner radius (cells)<input id="zoneInnerRadius" type="number" min="0" max="30" value="${z.innerRadius??0}"></label><label class="field">Outer radius (cells)<input id="zoneOuterRadius" type="number" min="0" max="30" value="${z.outerRadius??4}"></label><label class="field">Horizontal offset<input id="zoneOffsetX" type="number" min="-64" max="64" value="${z.offsetX??0}"></label><label class="field">Vertical offset<input id="zoneOffsetY" type="number" min="-44" max="44" value="${z.offsetY??0}"></label></div><label class="field">Name<input id="zoneName" maxlength="60" value="${esc(z.name)}"></label><label class="field">Overlay color<input id="zoneColor" type="color" value="${z.color}"></label><label class="field wide">Linked neighboring zones<div class="assignment-list">${world.zones.filter(other=>other.id!==z.id).map(other=>`<label><span><input type="checkbox" data-zone-link="${other.id}" ${(z.links??[]).includes(other.id)?'checked':''}> ${esc(other.name)}</span></label>`).join('')||''}</div></label><label class="field wide">What is this zone for?<textarea id="zonePurpose" rows="3" maxlength="1000">${esc(z.description)}</textarea></label><label class="field">Apply effect<select id="zoneTrigger">${options([['tick','Every tick while inside'],['enter','Once when entering']],z.trigger)}</select></label><label class="field">Affected objects<select id="zoneTargets">${options([['creatures','Creatures only'],['all','All objects']],z.creaturesOnly?'creatures':'all')}</select></label><label class="field">Required tag (optional)<select id="zoneFilterTag">${selectOptions(world.tagDefs,z.filterTag,'Any tag')}</select></label><label class="field">Optional stat condition<select id="zoneConditionStat">${selectOptions(world.stats,z.conditionStat,'No stat condition')}</select></label><label class="field">Comparison<select id="zoneOp">${options([['<','Less than'],['<=','Less than or equal'],['>','Greater than'],['>=','Greater than or equal'],['==','Equal'],['!=','Not equal']],z.op)}</select></label><label class="field">Threshold<input id="zoneThreshold" type="number" step="any" value="${z.threshold}"></label></div><div class="form-section">EFFECT ON MATCHING OBJECTS</div><div class="form-grid"><label class="field">Effect<select id="zoneEffect">${options([['none','No automatic effect / membership only'],['stat','Add / subtract one selected stat'],['tag','Add a defined tag'],['untag','Remove a defined tag']],z.effect)}</select></label><label class="field">Exact affected stat<select id="zoneStat">${selectOptions(world.stats,z.stat)}</select></label><label class="field">Amount<input id="zoneAmount" type="number" step="any" value="${z.amount}"></label><label class="field">Affected tag<select id="zoneTag">${selectOptions(world.tagDefs,z.tag)}</select></label></div><div class="checks"><label><input type="checkbox" id="zoneEnabled" ${z.enabled?'checked':''}> Zone enabled</label></div><div id="formError" class="form-error"></div><div class="dialog-actions">${old?'<button class="danger" id="deleteZone">Delete zone</button><button id="clearZoneCells">Clear painted zone cells</button>':''}<button id="cancelZone">Cancel</button><button class="primary" id="saveZone">Save zone</button></div>`);function fields(){const attached=$('zonePlacement').value==='attached',kind=$('zoneAnchorKind').value;for(const id of ['zoneAnchorKind','zoneShape','zoneInnerRadius','zoneOuterRadius','zoneOffsetX','zoneOffsetY'])$(id).disabled=!attached;for(const [id,k]of [['zoneAnchorEntity','entity'],['zoneAnchorTool','tool'],['zoneAnchorTag','tag']])$(id).disabled=!attached||kind!==k;const effect=$('zoneEffect').value;$('zoneStat').disabled=effect!=='stat';$('zoneAmount').disabled=effect!=='stat';$('zoneTag').disabled=!['tag','untag'].includes(effect);$('zoneOp').disabled=$('zoneConditionStat').value==='';$('zoneThreshold').disabled=$('zoneConditionStat').value==='';}fields();$('zonePlacement').onchange=fields;$('zoneAnchorKind').onchange=fields;$('zoneEffect').onchange=fields;$('zoneConditionStat').onchange=fields;$('cancelZone').onclick=()=>$('dialog').close();$('saveZone').onclick=()=>{Object.assign(z,{placement:$('zonePlacement').value,anchorKind:$('zoneAnchorKind').value,anchorEntity:$('zoneAnchorEntity').value,anchorTool:$('zoneAnchorTool').value,anchorTag:$('zoneAnchorTag').value,shape:$('zoneShape').value,innerRadius:num('zoneInnerRadius'),outerRadius:num('zoneOuterRadius'),offsetX:num('zoneOffsetX'),offsetY:num('zoneOffsetY'),name:$('zoneName').value.trim(),description:$('zonePurpose').value.trim(),links:[...$('dialogBody').querySelectorAll('[data-zone-link]:checked')].map(input=>input.dataset.zoneLink),color:$('zoneColor').value,trigger:$('zoneTrigger').value,creaturesOnly:$('zoneTargets').value==='creatures',filterTag:$('zoneFilterTag').value,conditionStat:$('zoneConditionStat').value,op:$('zoneOp').value,threshold:num('zoneThreshold'),effect:$('zoneEffect').value,stat:$('zoneStat').value,amount:num('zoneAmount'),tag:$('zoneTag').value,enabled:$('zoneEnabled').checked});if(z.placement==='painted'&&!old?.placement)for(const key of ['placement','anchorKind','anchorEntity','anchorTool','anchorTag','shape','innerRadius','outerRadius','offsetX','offsetY'])delete z[key];if(!z.name)return error('Name this zone.');if(z.effect==='stat'&&!z.stat)return error('Choose the exact stat to change.');if(['tag','untag'].includes(z.effect)&&!z.tag)return error('Choose a tag.');if(!old&&world.zones.length>=30)return error('Prototype limit: 30 zones.');const candidate=structuredClone(world);if(old)candidate.zones[candidate.zones.findIndex(v=>v.id===id)]=z;else candidate.zones.push(z);if(!validWorld(candidate))return error('Choose a valid anchor and integer radii / offsets. Outer radius must be at least the inner radius and no more than 30.');checkpoint();if(old)world.zones[world.zones.findIndex(zone=>zone.id===id)]=z;else world.zones.push(z);zoneId=z.id;changed();refresh();$('dialog').close();toast(z.placement==='attached'?'Attached zone saved. It follows its matching objects.':'Zone saved. Select it to paint the board.');};if(old){$('clearZoneCells').onclick=()=>{checkpoint();old.cells=[];changed();refresh();$('dialog').close();toast('Painted zone cells cleared; its definition and AI references remain.');};$('deleteZone').onclick=()=>{if(world.tools.some(t=>t.allowedMovementZones?.includes(id)||t.brain.some(n=>n.zoneId===id||n.scoreZone===id||n.patrolZones?.includes(id)||n.selectionZones?.includes(id))||t.decisions.some(d=>d.zoneId===id||d.scoreZone===id))||world.directors.some(d=>d.rules.some(r=>r.goalZone===id||r.testZone===id||r.fields?.some(f=>(f.type==='zone'&&f.source==='constant'&&f.value===id)||f.source==='zoneSnapshot'&&f.zoneId===id))))return error('An AI node or utility decision references this zone. Remove those references before deleting it.');checkpoint();world.zones=world.zones.filter(z=>z.id!==id);for(const other of world.zones)other.links=(other.links??[]).filter(link=>link!==id);for(const object of world.entities)if(object.inbox)object.inbox=object.inbox.filter(m=>!Object.values(m.fields??{}).some(f=>f.type==='zone'&&f.value===id));for(const e of world.entities)if(e.zoneMembership)e.zoneMembership=e.zoneMembership.filter(z=>z!==id);if(zoneId===id)zoneId=world.zones[0]?.id??null;changed();refresh();$('dialog').close();};}}
function tutorialBot(){return world.entities.find(e=>e.id===world.tutorial?.botId);}
function updateTutorialLive(){const live=$('tutorialLive');if(!live)return;const bot=tutorialBot();if(!bot){live.textContent='Your own project · replay the guide or open the pursuit demo.';return;}if(world.tutorial.kind!=='pursuit'){const charge=bot.stats[world.tutorial.chargeId];live.textContent='Tick '+world.tick+' · Charge '+Math.round(charge)+' / 100 · '+bot.action;return;}const subject=world.entities.find(e=>e.id===world.tutorial.subjectId),message=activeMessage(world,bot,'investigate'),director=world.directors.find(d=>d.id===world.tutorial.directorId),following=bot.activeNodes?.some(id=>{const n=toolOf(bot)?.brain.find(n=>n.id===id);return ((n?.action==='directive')||(n?.action==='moveTarget'&&bot.targets?.[n.slot]?.message))&&bot.nodeStatus?.[id]==='running';}),phase=following?'Investigating accepted hint':bot.tags.includes(world.tutorial.searchTag)?'Searching locally':'Local patrol';live.textContent='Tick '+world.tick+' · '+phase+(message&&!following?' · Hint queued':'')+' · Director '+(director?.enabled?'on':'off')+' · Subject signal strength '+(subject?.stats[world.tutorial.noiseId]??'—')+' · '+bot.action;}
function renderGuide(){if(world.tutorial?.kind!=='pursuit')return renderLegacyGuide();const card=$('tutorialGuide');card.classList.toggle('hidden',!guideOpen);if(!guideOpen)return;const steps=[['Patrol. Receive a hint. Investigate.','An editable pursuit lab with random roaming and obstacles that force detours. The light square is Pursuer; the darker square is Moving subject. Use Debug view to reveal collision, paths, hints and signals. It starts paused.','Run the example'],['Watch a suggestion become a decision.','With no message, Pursuer chooses points in Outer surroundings. The subject waits a random 8–24 ticks at each random destination, then emits activity. The director sends a fixed snapshot of Inner surroundings. Pursuer investigates, searches locally for twenty ticks, then resumes patrol.','Inspect the director'],['One flow: observation → message → tree.','This director observes only Moving subject. Its activity signal rule sends investigate with one area snapshot. Open Edit to disable the director: local patrol still works. Signal strength is an editable example stat, not fear or pacing.','See the pursuer tree'],['Utility scores and tree conditions work together.','The investigate branch adds a constant score of 4 to its score. Search scores 6; patrol scores 1. Memory sequences advance through separate actions without reselecting a point every tick. Message conditions gate investigation; Move reaches the stored location; a separate Acknowledge action handles the input. All nodes and interaction rules are editable.','Try zone painting'],['An area gives the hint its destination.','General area contains all walkable map cells and is assigned as the allowed movement zone for both creatures. Subject roaming range is larger than the pursuer’s outer band; its inner/outer radii and Choose point minimum distance control how far the subject travels. Outer surroundings is an editable roaming ring attached to Moving subject. Inner surroundings is a smaller attached area used for investigation. The director copies the inner area when activity is signaled. The receiver chooses a reachable point from that fixed copy. Edit the ring radii or select another zone in the message data.','Configure this area'],['Change the experiment, then run it again.','Rearrange the action chain. Choose inside or outside areas, use a stored location as an origin, change waits or history filters, and gate any chain with your conditions. The subject route is another ordinary behavior tree. Reset run restores the start of your test; New canvas remains blank.','Keep experimenting']];const [title,copy,action]=steps[guideStep];card.innerHTML=`<div class="tutorial-copy"><span class="eyebrow">PURSUIT LAB · ${guideStep+1} / 6</span><h2>${title}</h2><p>${copy}</p><div id="tutorialLive" class="tutorial-live"></div><div class="action-row"><button id="guideSubject">Inspect subject</button><button id="guidePursuer">Inspect pursuer</button><button id="guideDirector">Director</button></div></div><div class="tutorial-buttons"><div class="tour-dots">${steps.map((_,i)=>`<button data-guide-step="${i}" aria-label="Tutorial step ${i+1}" class="${i===guideStep?'current':''}"></button>`).join('')}</div><button id="tutorialAction" class="primary">${action}</button><div class="action-row">${guideStep?'<button id="tutorialBack">Back</button>':''}<button id="tutorialSkip">Close guide</button></div></div>`;card.querySelectorAll('[data-guide-step]').forEach(b=>b.onclick=()=>goGuide(Number(b.dataset.guideStep)));if($('tutorialBack'))$('tutorialBack').onclick=()=>goGuide(guideStep-1);$('tutorialSkip').onclick=()=>{guideOpen=false;document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));renderGuide();};$('tutorialAction').onclick=()=>{if(guideStep===0){goGuide(1);setRunning(true);}else if(guideStep===4){goGuide(5);editZone(zoneId);}else if(guideStep===5){guideOpen=false;switchView('board');renderGuide();}else goGuide(guideStep+1);};const inspect=(id,tid)=>{setRunning(false);entityId=id;toolId=tid;switchView('board');setMode('select');renderInspector();renderTools();draw();};$('guideSubject').onclick=()=>inspect(world.tutorial.subjectId,world.tutorial.subjectToolId);$('guidePursuer').onclick=()=>inspect(world.tutorial.botId,world.tutorial.toolId);$('guideDirector').onclick=()=>goGuide(2);updateTutorialLive();}
function renderLegacyGuide(){const card=$('tutorialGuide');card.classList.toggle('hidden',!guideOpen);if(!guideOpen)return;if(!world.tutorial){card.innerHTML='<div><span class="eyebrow">GUIDE</span><h2>Explore using your own project, or open the pursuit demo.</h2></div><div class="action-row"><button id="guideLoadHouse" class="primary">Open pursuit demo</button><button id="guideDismiss">Close guide</button></div>';$('guideLoadHouse').onclick=loadHouseDemo;$('guideDismiss').onclick=()=>{guideOpen=false;renderGuide();};return;}const steps=[['A house, two rooms, one small mind.','The walls are ordinary editable objects. The shaded rooms are zones. The bot is a creature with just one custom stat. Nothing is hidden: every part can be inspected and changed.','Run the bot'],['Watch the room-to-room loop.','Recharge raises Charge; Work lowers it. The bot uses utility scores plus a state-tag condition to decide which room to visit. Its wall-aware path passes through the doorway.','Inspect the bot'],['Its numbers belong to it.','The inspector shows Charge, its assigned tags, and the latest decision trace. Walls do not get a Charge stat. You can assign your own stats to each creature or object type.','See its behavior tree'],['Scores rank. Conditions decide.','The utility root ranks the two goals. State-tag conditions reject the wrong goal; zone conditions check arrival; movement actions find a path. Scroll the graph to inspect both branches.','Try zone painting'],['Draw an area, not an obstacle.','The zone is selected. Drag on the board to extend Room 1, or choose another zone. Erase zone removes only the selected zone cells; it does not erase blocks or add collision.','Configure this zone'],['Give the zone its meaning.','Choose an effect, exact stat, tag filter, and optional condition. In AI nodes, zones can be conditions, movement targets, or score multipliers. These are editable examples; New canvas still gives you a blank project.','Keep experimenting']];const [title,copy,action]=steps[guideStep];card.innerHTML=`<div class="tutorial-copy"><span class="eyebrow">INTERACTIVE INTRODUCTION · ${guideStep+1} / ${steps.length}</span><h2>${title}</h2><p>${copy}</p><div id="tutorialLive" class="tutorial-live"></div></div><div class="tutorial-buttons"><div class="tour-dots">${steps.map((_,i)=>`<button data-guide-step="${i}" aria-label="Tutorial step ${i+1}" class="${i===guideStep?'current':''}"></button>`).join('')}</div><button id="tutorialAction" class="primary">${action}</button><div class="action-row">${guideStep?'<button id="tutorialBack">Back</button>':''}<button id="tutorialSkip">Close guide</button></div></div>`;card.querySelectorAll('[data-guide-step]').forEach(b=>b.onclick=()=>goGuide(Number(b.dataset.guideStep)));if($('tutorialBack'))$('tutorialBack').onclick=()=>goGuide(guideStep-1);$('tutorialSkip').onclick=()=>{guideOpen=false;document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));renderGuide();};$('tutorialAction').onclick=()=>{if(guideStep===0){goGuide(1);setRunning(true);}else if(guideStep===4){goGuide(5);editZone(zoneId);}else if(guideStep===5){guideOpen=false;switchView('board');renderGuide();}else goGuide(guideStep+1);};updateTutorialLive();}
function goGuide(index){setRunning(false);guideOpen=true;guideStep=Math.max(0,Math.min(5,index));document.querySelectorAll('.tour-highlight').forEach(el=>el.classList.remove('tour-highlight'));if(world.tutorial){toolId=world.tutorial.toolId;entityId=world.tutorial.botId;if(guideStep===2&&world.tutorial.kind==='pursuit'){switchView('directors');$('directorCards').classList.add('tour-highlight');}else if(guideStep===3){switchView('behavior');$('brainContent').classList.add('tour-highlight');}else if(guideStep===5){switchView('zones');$('zoneCards').classList.add('tour-highlight');}else{switchView('board');setMode(guideStep===4?'zone':'select');if(guideStep===4){zoneId=(world.tutorial.primaryZone??world.tutorial.chargingZone);setMode('zone');renderZones();$('zoneBrushes').classList.add('tour-highlight');}if(guideStep===2)$('inspector').classList.add('tour-highlight');}renderInspector();renderTools();draw();}renderGuide();}
function loadHouseDemo(){modal('Open a fresh pursuit demo?','<div class="dialog-actions"><button id="cancelHouse">Cancel</button><button class="primary" id="confirmHouse">Open pursuit demo</button></div>');$('cancelHouse').onclick=()=>$('dialog').close();$('confirmHouse').onclick=()=>{setRunning(false);const currentId=collaboration?.active()?world.id:null,fresh=createDemoWorld();if(currentId)fresh.id=currentId;world=fresh;toolId=world.tutorial.toolId;entityId=world.tutorial.botId;zoneId=(world.tutorial.primaryZone??world.tutorial.chargingZone);guideOpen=true;guideStep=0;baseline=null;undo=[];redo=[];zoom=1.45;pan={x:0,y:0};imageCache.clear();librariesInitialized=false;changed();$('dialog').close();switchView('board');setMode('select');refresh();};}
$('newZone').onclick=$('quickNewZone').onclick=()=>editZone();$('tutorialReplay').onclick=()=>{guideOpen=true;goGuide(0);};$('reloadHouse').onclick=loadHouseDemo;

const zoneBaseHelp=$('help').onclick;$('help').onclick=()=>{zoneBaseHelp();$('dialogBody').insertAdjacentHTML('afterbegin','<p><b>Pursuit introduction:</b> Open Pursuit demo for an editable subject, director and pursuer. Inspect the graphs to configure patrol destinations, pauses, varied routes, message commitment and local search. Debug view shows the chosen point and actual route. Guide replays the explanation; Pursuit demo creates a fresh teaching copy after confirming replacement. Saved projects remain in Projects.</p><p><b>Zones:</b> Use Zone to paint the selected area and Unzone to erase only that zone. Zones never create collision. Configure entry/tick effects, selected stats or tags, required tags, and optional stat conditions in Zones. In AI nodes, use zone conditions, Go to zone actions, or a zone score multiplier. Scores still work alongside tree conditions. Effects never attach missing stats.</p>');};
function renderDirectors(){$('directorCount').textContent=world.directors.length;$('directorCards').innerHTML=world.directors.length?world.directors.map(d=>`<article class="director-card"><div class="creature-card-title"><h3>${esc(d.name)}</h3><span class="tag">${d.enabled?'Enabled':'Disabled'}</span></div><p>${esc(d.description)||'Central observation and communication, without built-in pacing.'}</p><div class="zone-meta"><span>Observe: ${esc(world.tools.find(t=>t.id===d.watchTool)?.name??'all object types')}${d.watchTag?' / '+esc(tagDef(d.watchTag)?.name):''}${d.watchEntity?' / one selected instance':''}</span><span>Recipients: ${d.recipients.length} creature(s)</span><span>${d.rules.length} rules</span></div><div class="action-row"><button data-director-edit="${d.id}">Observation & receivers</button><button data-director-rule="${d.id}">＋ Event → message rule</button><button data-director-connect="${d.id}">Message routing</button></div>${d.rules.map(r=>`<div class="mini-row"><span>${esc(r.name)}<small>${r.enabled?'On':'Off'} · ${esc(r.trigger)} → ${esc(r.message)} · ${esc(messageFieldsForRule(r).map(f=>f.name+': '+f.type).join(', '))} · ${r.ttl} ticks</small></span><button data-rule-owner="${d.id}" data-director-rule-edit="${r.id}">Edit</button></div>`).join('')}<div class="director-live" id="directorLive-${d.id}"></div></article>`).join(''):empty('Empty');for(const [key,handler]of [['edit',id=>editDirector(id)],['rule',id=>editDirectorRule(id)],['connect',id=>editDirectorReceiver(id)]])$('directorCards').querySelectorAll('[data-director-'+key+']').forEach(b=>b.onclick=()=>handler(b.dataset['director'+key[0].toUpperCase()+key.slice(1)]));$('directorCards').querySelectorAll('[data-director-rule-edit]').forEach(b=>b.onclick=()=>editDirectorRule(b.dataset.ruleOwner,b.dataset.directorRuleEdit));updateDirectorLive();}
function updateDirectorLive(){for(const d of world.directors){const live=$('directorLive-'+d.id);if(!live)continue;live.innerHTML=`<details><summary>Observations (${d.observations.length}) and delivery trace</summary>${d.observations.map(o=>`<div class="director-observation"><strong>${esc(world.tools.find(t=>t.id===o.toolId)?.name??'Object')} (${o.x}, ${o.y})</strong><span>${Object.entries(o.stats).map(([key,value])=>`${esc(world.stats.find(s=>s.id===key)?.name??key)} ${Number(value.toFixed(2))}`).join(' · ')||'No stats'}</span><span>${o.zones.map(id=>esc(world.zones.find(z=>z.id===id)?.name??'')).join(', ')||'Outside zones'}</span></div>`).join('')||''}<div class="trace">${d.log.slice(-12).reverse().map(l=>`T${l.tick} · ${esc(l.text)}`).join('<br>')||'No messages delivered yet.'}</div></details>`;}}
function editDirector(id){setRunning(false);const old=world.directors.find(d=>d.id===id),d=structuredClone(old??makeDirector());modal(old?'Edit director':'Create director',`<div class="form-grid"><label class="field">Name<input id="directorName" maxlength="60" value="${esc(d.name)}"></label><label class="field">Observed object type<select id="directorWatchTool">${selectOptions(world.tools,d.watchTool,'All object types')}</select></label><label class="field">Observed tag (optional)<select id="directorWatchTag">${selectOptions(world.tagDefs,d.watchTag,'Any tag')}</select></label><label class="field">Exact observed instance (optional)<select id="directorWatchEntity">${selectOptions(world.entities.map(e=>({id:e.id,name:`${toolOf(e)?.name??'Object'} (${e.x}, ${e.y})`})),d.watchEntity,'All matching instances')}</select></label><label class="field wide">Purpose<textarea id="directorPurpose" rows="3" maxlength="1000">${esc(d.description)}</textarea></label><div class="field wide">Message receivers<div class="assignment-list">${world.tools.filter(t=>t.kind==='creature').map(t=>`<label><span><input type="checkbox" data-director-recipient="${t.id}" ${d.recipients.includes(t.id)?'checked':''}> ${esc(t.name)}</span></label>`).join('')||''}</div></div></div><div class="checks"><label><input type="checkbox" id="directorEnabled" ${d.enabled?'checked':''}> Director enabled</label></div><div id="formError" class="form-error"></div><div class="dialog-actions">${old?'<button id="deleteDirector" class="danger">Delete director</button>':''}<button id="cancelDirector">Cancel</button><button class="primary" id="saveDirector">Save director</button></div>`);$('cancelDirector').onclick=()=>$('dialog').close();$('saveDirector').onclick=()=>{const name=$('directorName').value.trim();if(!name)return error('Name the director.');if(!old&&world.directors.length>=10)return error('Prototype limit: 10 directors.');const watchTool=$('directorWatchTool').value,watchTag=$('directorWatchTag').value,watchEntity=$('directorWatchEntity').value;const filterChanged=d.watchTool!==watchTool||d.watchTag!==watchTag||d.watchEntity!==watchEntity;Object.assign(d,{name,description:$('directorPurpose').value.trim(),watchTool,watchTag,watchEntity,enabled:$('directorEnabled').checked,recipients:[...$('dialogBody').querySelectorAll('[data-director-recipient]:checked')].map(input=>input.dataset.directorRecipient)});if(filterChanged){d.memory={};d.observations=[];for(const rule of d.rules)rule.state={};}checkpoint();if(old)world.directors[world.directors.findIndex(x=>x.id===id)]=d;else world.directors.push(d);changed();refresh();$('dialog').close();toast('Director saved. Add a rule and connect its message receiver.');};if(old)$('deleteDirector').onclick=()=>{checkpoint();world.directors=world.directors.filter(d=>d.id!==id);for(const e of world.entities)if((world.messageRoutes??[]).some(r=>r.directorId===id&&r.messageId===e.acceptedMessage?.message.id))delete e.acceptedMessage;for(const e of world.entities)e.inbox=(e.inbox??[]).filter(m=>!(world.messageRoutes??[]).some(r=>r.directorId===id&&r.messageId===m.id));changed();refresh();$('dialog').close();};}
function editDirectorRule(owner,id){setRunning(false);const d=world.directors.find(d=>d.id===owner),old=d.rules.find(r=>r.id===id),r=structuredClone(old??makeDirectorRule());r.fields=old?messageFieldsForRule(r):[];
modal('Director observation → message',`<div class="form-grid"><label class="field">Rule name<input id="directorRuleName" maxlength="80" value="${esc(r.name)}"></label><label class="field">When<select id="directorTrigger">${options([['move','Source object moves'],['stat','Source stat passes a condition'],['enter','Source object enters a zone'],['exit','Source object leaves a zone'],['signal','Source object emits a named signal'],['always','Source matches / every eligible tick']],r.trigger)}</select></label><label class="field">Source stat<select id="directorStat">${selectOptions(world.stats,r.statId)}</select></label><label class="field">Comparison<select id="directorOp">${options([['<','<'],['<=','≤'],['>','>'],['>=','≥'],['==','='],['!=','≠']],r.op)}</select></label><label class="field">Threshold<input id="directorThreshold" type="number" step="any" value="${r.threshold}"></label><label class="field">Source zone<select id="directorTestZone">${selectOptions(world.zones,r.testZone)}</select></label><label class="field">Signal name<input id="directorSignal" maxlength="60" value="${esc(r.signal)}"></label></div><div class="form-section">MESSAGE</div><div class="form-grid"><label class="field">Message name<input id="directorMessage" maxlength="60" value="${esc(r.message)}"></label><label class="field">Lifetime (ticks)<input id="directorTTL" type="number" min="1" max="10000" value="${r.ttl}"></label><label class="field">Cooldown per source (ticks)<input id="directorCooldown" type="number" min="1" max="10000" value="${r.cooldown}"></label></div><div class="inline-title"><h3>Message data</h3><button id="addMessageField">＋ Add data value</button></div><div id="messageFieldRows"></div><div class="checks"><label><input id="directorRuleEnabled" type="checkbox" ${r.enabled?'checked':''}> Rule enabled</label><label><input id="directorRepeat" type="checkbox" ${r.repeat?'checked':''}> Repeat while condition stays true</label></div><div id="formError" class="form-error"></div><div class="dialog-actions">${old?'<button class="danger" id="deleteDirectorRule">Delete rule</button>':''}<button id="cancelDirectorRule">Cancel</button><button class="primary" id="saveDirectorRule">Save event → message rule</button></div>`);
const sourceOptions={number:[['constant','Constant'],['subjectStat','Source stat'],['signalValue','Signal value']],text:[['constant','Constant']],boolean:[['constant','Constant'],['subjectTag','Source tag present']],zone:[['constant','Selected zone'],['subjectZone','Source object’s current zone'],['linkedZone','Linked zone']],area:[['zoneSnapshot','Snapshot of selected zone']],position:[['constant','Selected coordinates'],['subjectPosition','Source object’s position'],['signalPosition','Signal origin position']]};
function readFields(){return r.fields.map((f,i)=>{const type=$('messageFieldType'+i).value,source=$('messageFieldSource'+i).value,result={name:$('messageFieldName'+i).value.trim(),type,source};if(source==='constant')result.value=type==='number'?num('messageFieldValue'+i):type==='boolean'?$('messageFieldBoolean'+i).value==='true':type==='zone'?$('messageFieldZone'+i).value:type==='position'?{x:num('messageFieldX'+i),y:num('messageFieldY'+i)}:$('messageFieldValue'+i).value;if(source==='zoneSnapshot')result.zoneId=$('messageFieldZone'+i).value;if(source==='subjectStat')result.statId=$('messageFieldStat'+i).value;if(source==='subjectTag')result.tagId=$('messageFieldTag'+i).value;return result;});}
function renderFields(){$('messageFieldRows').innerHTML=r.fields.map((f,i)=>{const sources=sourceOptions[f.type];if(!sources.some(([v])=>v===f.source))f.source='constant';const constant=f.source==='constant';return `<div class="message-field-card"><div class="form-grid"><label class="field">Data name<input id="messageFieldName${i}" maxlength="40" value="${esc(f.name)}"></label><label class="field">Type<select id="messageFieldType${i}">${options([['number','Number'],['text','Text'],['boolean','Boolean'],['zone','Zone reference'],['area','Area snapshot'],['position','Position']],f.type)}</select></label><label class="field">Value source<select id="messageFieldSource${i}">${options(sources,f.source)}</select></label><label class="field ${constant&&['number','text'].includes(f.type)?'':'hidden'}">Value<input id="messageFieldValue${i}" type="${f.type==='number'?'number':'text'}" step="any" maxlength="500" value="${esc(typeof f.value==='number'||typeof f.value==='string'?f.value:f.type==='number'?0:'')}"></label><label class="field ${constant&&f.type==='boolean'?'':'hidden'}">Value<select id="messageFieldBoolean${i}">${options([['true','True'],['false','False']],f.value===false?'false':'true')}</select></label><label class="field ${(constant&&f.type==='zone'||f.source==='zoneSnapshot')?'':'hidden'}">Zone<select id="messageFieldZone${i}">${selectOptions(world.zones,f.source==='zoneSnapshot'?f.zoneId:f.value)}</select></label><label class="field ${constant&&f.type==='position'?'':'hidden'}">X<input id="messageFieldX${i}" type="number" value="${f.value?.x??0}"></label><label class="field ${constant&&f.type==='position'?'':'hidden'}">Y<input id="messageFieldY${i}" type="number" value="${f.value?.y??0}"></label><label class="field ${f.source==='subjectStat'?'':'hidden'}">Stat<select id="messageFieldStat${i}">${selectOptions(world.stats,f.statId)}</select></label><label class="field ${f.source==='subjectTag'?'':'hidden'}">Tag<select id="messageFieldTag${i}">${selectOptions(world.tagDefs,f.tagId)}</select></label></div><button data-remove-message-field="${i}">Remove data</button></div>`;}).join('');for(let i=0;i<r.fields.length;i++){const change=()=>{r.fields=readFields();renderFields();};$('messageFieldType'+i).onchange=change;$('messageFieldSource'+i).onchange=change;}$('messageFieldRows').querySelectorAll('[data-remove-message-field]').forEach(b=>b.onclick=()=>{r.fields=readFields();r.fields.splice(Number(b.dataset.removeMessageField),1);renderFields();});}
renderFields();$('addMessageField').onclick=()=>{r.fields=readFields();if(r.fields.length>=20)return error('Maximum 20 message data values.');r.fields.push({name:'data'+(r.fields.length+1),type:'text',source:'constant',value:''});renderFields();};
function fields(){const trigger=$('directorTrigger').value;for(const key of ['directorStat','directorOp','directorThreshold'])$(key).disabled=trigger!=='stat';$('directorTestZone').disabled=!['enter','exit'].includes(trigger);$('directorSignal').disabled=trigger!=='signal';}fields();$('directorTrigger').onchange=fields;$('cancelDirectorRule').onclick=()=>$('dialog').close();
$('saveDirectorRule').onclick=()=>{Object.assign(r,{fields:readFields(),captureStat:'',destination:'none',goalZone:'',weight:1,name:$('directorRuleName').value.trim(),trigger:$('directorTrigger').value,statId:$('directorStat').value,op:$('directorOp').value,threshold:num('directorThreshold'),testZone:$('directorTestZone').value,signal:$('directorSignal').value.trim(),message:$('directorMessage').value.trim(),ttl:num('directorTTL',60),cooldown:num('directorCooldown',5),repeat:$('directorRepeat').checked,enabled:$('directorRuleEnabled').checked,state:{},seenSignals:[]});if(!r.name||!r.message)return error('Name the rule and message.');if(!old&&d.rules.length>=20)return error('Maximum 20 rules per director.');const candidate=structuredClone(world),director=candidate.directors.find(v=>v.id===owner);if(old)director.rules[director.rules.findIndex(v=>v.id===id)]=r;else director.rules.push(r);if(!validWorld(candidate))return error('Check the trigger, unique message data names, sources, values, and tick limits.');checkpoint();d.rules=director.rules;changed();refresh();$('dialog').close();};
if(old)$('deleteDirectorRule').onclick=()=>{checkpoint();const removed=new Set((world.messageRoutes??[]).filter(route=>route.ruleId===id).map(route=>route.messageId));d.rules=d.rules.filter(rule=>rule.id!==id);for(const e of world.entities){if(removed.has(e.acceptedMessage?.message.id))delete e.acceptedMessage;e.inbox=(e.inbox??[]).filter(m=>!removed.has(m.id));}world.messageRoutes=(world.messageRoutes??[]).filter(route=>route.ruleId!==id);world.messageDebug=(world.messageDebug??[]).filter(record=>record.ruleId!==id);changed();refresh();$('dialog').close();};}

function editDirectorReceiver(owner){setRunning(false);const d=world.directors.find(d=>d.id===owner),recipients=world.tools.filter(t=>d.recipients.includes(t.id)&&t.kind==='creature');modal('Build a message-handling chain',`<label class="field">Message receiver<select id="receiverTool">${selectOptions(recipients,recipients[0]?.id,'Choose a receiver')}</select></label><p>Message names: ${d.rules.map(r=>esc(r.message)).join(', ')||'Add an event → message rule to define a name.'}</p><div class="dialog-actions"><button id="closeReceiverGuide">Close</button><button class="primary" id="openReceiverGraph">Open receiver graph</button></div>`);$('closeReceiverGuide').onclick=()=>$('dialog').close();$('openReceiverGraph').onclick=()=>{if(!$('receiverTool').value)return toast('Choose a receiver.');toolId=$('receiverTool').value;entityId=null;$('dialog').close();switchView('behavior');renderInspector();};}
function editObservedInstance(e){setRunning(false);modal('Instance input / director test',`<div class="form-grid"><label class="field">X<input id="observedX" type="number" min="0" max="${WIDTH-1}" value="${e.x}"></label><label class="field">Y<input id="observedY" type="number" min="0" max="${HEIGHT-1}" value="${e.y}"></label><label class="field">Signal name<input id="observedSignal" maxlength="60" placeholder="Your own event name"></label><label class="field">Capture owned stat (optional)<select id="observedSignalStat">${selectOptions(ownedStats(toolOf(e)),'','No numeric value')}</select></label></div><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="closeObserved">Close</button><button id="moveObserved">Move instance</button><button class="primary" id="signalObserved">Emit signal</button></div>`);$('closeObserved').onclick=()=>$('dialog').close();$('moveObserved').onclick=()=>{const x=num('observedX'),y=num('observedY');if(!Number.isInteger(x)||!Number.isInteger(y)||x<0||x>=WIDTH||y<0||y>=HEIGHT)return error('Choose a valid board cell.');if(world.entities.some(other=>other!==e&&other.x===x&&other.y===y&&toolOf(other)?.collision))return error('That cell is blocked by a solid object.');checkpoint();e.x=x;e.y=y;changed();refresh();toast('Instance moved. Advance a tick for the director to observe it.');};$('signalObserved').onclick=()=>{const name=$('observedSignal').value.trim();if(!name)return error('Name the signal.');checkpoint();const signal=sendSignal(world,e,name,$('observedSignalStat').value);if(!signal)return error('The selected signal value is not available.');emit(world,(toolOf(e)?.name??'Object')+' emitted '+name+'.');changed();renderEvents();toast('Signal emitted. Advance a tick to process it.');};}
$('newDirector').onclick=()=>editDirector();

// Display-only overlays. Toggling these never edits the world or advances its clock.
function drawDebug(ctx,ox,oy,size,rect){const enabled=$('debugEnabled').checked;for(const id of ['debugCollision','debugPaths','debugHints','debugSignals','debugLabels','debugAll'])$(id).disabled=!enabled;if(!enabled){$('debugReadout').textContent='Overlays off. Simulation behavior is unchanged.';return;}const all=$('debugAll').checked,key=revision+'|'+world.tick+'|'+(entityId??'')+'|'+all;if(debugRenderCache.key!==key){const snapshot=debugSnapshot(world,entityId,all),readout=snapshot.actors.length?snapshot.actors.map(a=>{const scores=a.scores.map(s=>esc(s.name)+': '+s.score.toFixed(2)+' ('+esc(s.status)+')').join(' · '),hints=snapshot.links.filter(l=>l.recipientId===a.id).map(l=>(l.handling?'Handling: ':'Available message: ')+esc(l.director)+' → '+esc(l.message)+(l.zoneName?' → '+esc(l.zoneName):' (data only)')+' · value '+(l.value??'none')+' · '+(l.expires-world.tick)+' ticks left').join('; ');return '<div><strong>'+esc(a.name)+'</strong> · '+esc(a.action)+(a.goal?' · Goal: '+esc(a.goal.name)+(a.goal.point?' → point ('+a.goal.point.x+', '+a.goal.point.y+')':'')+(a.goal.waiting?' (pausing)':a.goal.reachable?'':' (unreachable)'):'')+(scores?'<small>Scores now / last branch result: '+scores+'</small>':'')+(hints?'<small>'+hints+'</small>':'')+(Object.keys(a.targets??{}).length?'<small>Stored locations: '+Object.entries(a.targets).map(([k,p])=>esc(k)+' = ('+p.x+', '+p.y+')').join(' · ')+'</small>':'')+(Object.keys(a.histories??{}).length?'<small>Location histories: '+Object.entries(a.histories).map(([k,v])=>esc(k)+' ['+v.length+' entries]').join(' · ')+'</small>':'')+'</div>';}).join(''):'No creature selected.';debugRenderCache={key,snapshot,readout};}const {snapshot,readout}=debugRenderCache,readoutEl=$('debugReadout'),point=p=>({x:ox+(p.x+.5)*size,y:oy+(p.y+.5)*size});if(readoutEl.innerHTML!==readout)readoutEl.innerHTML=readout;
ctx.save();ctx.beginPath();ctx.rect(ox,oy,WIDTH*size,HEIGHT*size);ctx.clip();
const label=(text,x,y,small=false)=>{ctx.font=(small?'13':'14')+'px monospace';const width=Math.min(rect.width-16,ctx.measureText(text).width+12),px=Math.max(5,Math.min(rect.width-width-5,x)),py=Math.max(5,Math.min(rect.height-28,y));ctx.fillStyle='#11161eef';ctx.fillRect(px,py,width,25);ctx.strokeStyle='#a8afb8';ctx.lineWidth=.6;ctx.setLineDash([]);ctx.strokeRect(px,py,width,25);ctx.fillStyle='#f0f2f5';ctx.fillText(text,px+6,py+17);};
const area=(cells,dash=[3,3])=>{const set=new Set(cells);ctx.setLineDash(dash);ctx.strokeStyle='#f0f2f5';ctx.lineWidth=1.5;for(const cell of cells){const x=cell%WIDTH,y=Math.floor(cell/WIDTH),px=ox+x*size,py=oy+y*size;ctx.beginPath();if(x===0||!set.has(cell-1)){ctx.moveTo(px,py);ctx.lineTo(px,py+size);}if(x===WIDTH-1||!set.has(cell+1)){ctx.moveTo(px+size,py);ctx.lineTo(px+size,py+size);}if(y===0||!set.has(cell-WIDTH)){ctx.moveTo(px,py);ctx.lineTo(px+size,py);}if(y===HEIGHT-1||!set.has(cell+WIDTH)){ctx.moveTo(px,py+size);ctx.lineTo(px+size,py+size);}ctx.stroke();}ctx.setLineDash([]);};
if($('debugCollision').checked){ctx.strokeStyle='#dddddd';ctx.lineWidth=.8;ctx.setLineDash([]);for(const cell of snapshot.collisions){const x=ox+cell.x*size+1,y=oy+cell.y*size+1,s=size-2;ctx.strokeRect(x,y,s,s);ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+s,y+s);ctx.moveTo(x+s,y);ctx.lineTo(x,y+s);ctx.stroke();}}
if($('debugPaths').checked)for(const a of snapshot.actors){if(a.goal?.kind==='zone'){area(a.goal.cells);if(a.goal.point){const p=point(a.goal.point);ctx.setLineDash([]);ctx.strokeStyle='#f5f5f5';ctx.strokeRect(p.x-4,p.y-4,8,8);}}if(a.goal?.kind==='object')area([a.goal.y*WIDTH+a.goal.x]);if(a.path.length>1){ctx.setLineDash([]);ctx.strokeStyle='#f5f5f5';ctx.lineWidth=1.8;ctx.beginPath();a.path.forEach((p,i)=>{const q=point(p);if(i)ctx.lineTo(q.x,q.y);else ctx.moveTo(q.x,q.y);});ctx.stroke();const last=point(a.path.at(-1));ctx.beginPath();ctx.arc(last.x,last.y,Math.max(3,size*.3),0,Math.PI*2);ctx.stroke();}}
if($('debugHints').checked)for(const hint of snapshot.links){if(hint.cells.length)area(hint.cells,[8,4]);const from=point(hint.from),to=point(hint.to);ctx.strokeStyle='#bfc6ce';ctx.lineWidth=1.2;ctx.setLineDash([8,5]);ctx.beginPath();ctx.moveTo(from.x,from.y);ctx.lineTo(to.x,to.y);ctx.stroke();ctx.setLineDash([]);ctx.strokeRect(from.x-3,from.y-3,6,6);label((hint.handling?'handling: ':'available: ')+hint.message,(from.x+to.x)/2,(from.y+to.y)/2,true);}
if($('debugSignals').checked)for(const signal of snapshot.signals){const p=point(signal);ctx.strokeStyle='#e2e6eb';ctx.lineWidth=1.2;ctx.setLineDash([2,3]);ctx.beginPath();ctx.arc(p.x,p.y,size*(.6+(world.tick-signal.tick)*.12),0,Math.PI*2);ctx.stroke();ctx.setLineDash([]);label(signal.name+' · tick '+signal.tick,p.x+size,p.y+size,true);}
if($('debugLabels').checked)for(const a of snapshot.actors){const p=point(a);label(a.name,p.x+size,p.y-60);label((a.branch||a.action||'Not evaluated').slice(0,52),p.x+size,p.y-33,true);}
ctx.restore();}

for(const id of ['debugEnabled','debugCollision','debugPaths','debugHints','debugSignals','debugLabels','debugAll'])$(id).onchange=requestDraw;

function isSplitWorkspace(){return splitEnabled&&(view==='board'||view==='behavior');}
function treeVisible(){return view==='behavior'||isSplitWorkspace();}
function updateWorkspace(){const active=isSplitWorkspace();$('editorLayout').classList.toggle('split-active',active);$('editorLayout').classList.toggle('inspector-open',active&&splitInspector);$('simulationWorkspace').classList.toggle('split-mode',active);$('simulationWorkspace').classList.toggle('hidden',!['board','behavior'].includes(view));for(const k of ['board','tools','stats','rules','tags','behavior','history','creatures','zones','directors'])$(k+'View').classList.toggle('hidden',!(k===view||active&&['board','behavior'].includes(k)));$('toggleSplit').ariaPressed=String(splitEnabled);$('toggleInspector').classList.toggle('hidden',!active);$('toggleInspector').ariaPressed=String(splitInspector);$('toggleInspector').textContent=splitInspector?'Hide inspector':'Show inspector';}
$('toggleSplit').onclick=()=>{splitEnabled=!splitEnabled;switchView(['board','behavior'].includes(view)?view:'board');requestDraw();};$('toggleInspector').onclick=()=>{splitInspector=!splitInspector;updateWorkspace();requestDraw();};

const ANALYTICS_CONSENT_KEY='prototeer.analytics-consent.v1',ANALYTICS_PARTICIPANT_KEY='prototeer.analytics-participant.v1',ANALYTICS_UI_VERSION='dev-2026-11-23-lobby';
const analyticsSessionId=('session_'+(crypto.randomUUID?.()??`${Date.now()}_${Math.random().toString(36).slice(2)}`)).replace(/[^A-Za-z0-9_-]/g,'_').slice(0,100);
const analyticsPanel=()=>({tools:'object-types',zones:'zones',creatures:'creatures',stats:'stats',rules:'interaction-rules',tags:'tags',behavior:'behavior-tree',directors:'directors',history:'history',board:'board'}[view]??'unknown');
const allowedAnalyticsControls=()=>[...document.querySelectorAll('[id]')].map(element=>element.id).filter(id=>/^[A-Za-z][A-Za-z0-9_-]{0,79}$/.test(id));
function analyticsTransport(){return collaboration?.analyticsTransport?.()??null;}
function setUsageConsent(value){analyticsConsent=value===true;try{localStorage.setItem(ANALYTICS_CONSENT_KEY,analyticsConsent?'yes':'no');}catch{}analytics?.setConsent(analyticsConsent);$('usageConsent').hidden=true;}
function setupAnalytics(){if(analytics||!globalThis.PrototeerAnalytics)return;const transport=analyticsTransport();if(!transport){$('usageConsent').hidden=true;return;}let choice='';try{choice=localStorage.getItem(ANALYTICS_CONSENT_KEY)??'';}catch{}analyticsConsent=choice==='yes';let participant='';try{participant=localStorage.getItem(ANALYTICS_PARTICIPANT_KEY)??'';}catch{}if(!/^[A-Za-z0-9_-]{12,100}$/.test(participant)){participant=('participant_'+(crypto.randomUUID?.()??`${Date.now()}_${Math.random().toString(36).slice(2)}`)).replace(/[^A-Za-z0-9_-]/g,'_').slice(0,100);try{localStorage.setItem(ANALYTICS_PARTICIPANT_KEY,participant);}catch{}}analytics=globalThis.PrototeerAnalytics.createAnalytics({sessionId:analyticsSessionId,participantId:participant,uiVersion:ANALYTICS_UI_VERSION,consent:analyticsConsent,allowedControls:allowedAnalyticsControls(),transport});$('usageConsent').hidden=choice==='yes'||choice==='no';}
$('allowUsage').onclick=()=>setUsageConsent(true);$('declineUsage').onclick=()=>setUsageConsent(false);
function analyticsRegion(target){const region=target?.closest?.('[data-analytics-region]'),name=region?.dataset.analyticsRegion;const surface=name==='board'?'board':'ui';const panel=name==='projects'?'projects':name==='header'?'header':name==='inspector'?'inspector':name==='dialog'?$('dialogTitle').textContent==='Your projects'?'projects':$('dialogTitle').textContent==='Share project'?'share':'dialog':analyticsPanel();return {region,surface,panel};}
function analyticsControlId(target){const element=target?.closest?.('button,a,[role="button"]');if(!element)return '';if(element.id)return element.id;const key=Object.keys(element.dataset??{}).sort()[0];return key?`action_${key.replace(/([A-Z])/g,'_$1').toLowerCase()}`:`action_${element.tagName?.toLowerCase()==='a'?'link':'button'}`;}
let lastPointerAnalytics=0,lastScrollAnalytics=0;
document.addEventListener?.('click',event=>{if(!analytics?.hasConsent())return;const {region,surface,panel}=analyticsRegion(event.target),control=analyticsControlId(event.target),rect=region?.getBoundingClientRect?.();if(control&&analytics.allowControl(control))analytics.record('control_clicked',{surface,panel,controlId:control});if(rect?.width&&rect?.height)analytics.sampleHeatmap('click',{surface,panel,x:event.clientX-rect.left,y:event.clientY-rect.top,width:rect.width,height:rect.height,pointerType:event.pointerType??'mouse'});},true);
document.addEventListener?.('pointermove',event=>{if(!analytics?.hasConsent())return;const timestamp=Date.now();if(timestamp-lastPointerAnalytics<100)return;lastPointerAnalytics=timestamp;const {region,surface,panel}=analyticsRegion(event.target),rect=region?.getBoundingClientRect?.();if(rect?.width&&rect?.height)analytics.sampleHeatmap('pointer',{surface,panel,x:event.clientX-rect.left,y:event.clientY-rect.top,width:rect.width,height:rect.height,pointerType:event.pointerType??'unknown'});},true);
document.addEventListener?.('scroll',event=>{if(!analytics?.hasConsent())return;const timestamp=Date.now();if(timestamp-lastScrollAnalytics<250)return;lastScrollAnalytics=timestamp;const target=event.target===document?document.documentElement:event.target,{region,surface,panel}=analyticsRegion(target),height=Math.max(1,target.scrollHeight-target.clientHeight),depth=Math.max(0,Math.min(1,(target.scrollTop??globalThis.scrollY??0)/height));analytics.sampleHeatmap('scroll',{surface,panel,scrollDepth:depth,width:region?.clientWidth??globalThis.innerWidth??1,height:region?.clientHeight??globalThis.innerHeight??1});},true);
document.addEventListener?.('change',event=>{const control=event.target?.id;if(!control||!analytics?.hasConsent()||!analytics.allowControl(control))return;const type=event.target.type==='checkbox'?'toggle':event.target.tagName==='SELECT'?'select':event.target.type==='number'?'number':event.target.type==='color'?'color':event.target.type==='file'?'file':'text';analytics.record('control_changed',{panel:analyticsRegion(event.target).panel,controlId:control,context:{settingType:type}});},true);

function setSyncState(state,role='local'){const el=$('syncState');el.dataset.state=state==='local'?'local':state;el.textContent=state==='local'?'Local':state==='syncing'?'Syncing…':state==='offline'?'Offline':state==='conflict'?'Conflict':role==='owner'?'Owner · synced':role==='editor'?'Editor · synced':'View only';const viewer=collaboration?.active()&&!collaboration.canEdit();$('projectName').readOnly=viewer;$('save').disabled=viewer;$('play').disabled=viewer;$('step').disabled=viewer;$('reset').disabled=viewer;const shared=collaboration?.active();$('undo').disabled=shared;$('redo').disabled=shared;}
function renderPresence(entries=[]){$('presence').innerHTML=entries.slice(0,5).map(person=>`<span class="presence-avatar" style="background:${esc(person.color)}" title="${esc(person.displayName)} · ${esc(person.role)}">${esc(person.initials)}</span>`).join('')+(entries.length>5?`<span class="presence-more">+${entries.length-5}</span>`:'');$('remotePointers').innerHTML=entries.filter(person=>!person.self&&person.view==='board'&&Number.isFinite(person.pointerX)&&Number.isFinite(person.pointerY)).map(person=>`<span class="remote-pointer" style="left:${100*person.pointerX}%;top:${100*person.pointerY}%;color:${esc(person.color)}"><span>${esc(person.displayName)}</span></span>`).join('');}
function applyRuntimeFrame(data){data=normalizeWorld(data);if(!validWorld(data))return;applyingRemote=true;world=data;applyingRemote=false;revision++;runtimeRevision++;renderRuntime();}
function initializeCollaboration(){if(!globalThis.PrototeerCollaboration)return;collaboration=globalThis.PrototeerCollaboration.create({preview:previewOf,hooks:{onBootstrap:(data,meta)=>applyRemoteProject(data,meta.preserveUi),onRemoteOperation:operation=>applyRemoteOperation(operation),onRemoteOperations:operations=>applyRemoteOperations(operations),onPresence:renderPresence,onStatus:status=>{setSyncState(status.state,status.role);if(status.active&&status.state==='synced')$('saveState').textContent='Synced';},onConflict:()=>toast('A collaborator changed the same item. The latest shared version was loaded.'),onError:()=>toast('Shared edits are waiting for the connection.'),onSimulation:state=>setRunning(state.status==='running',true,state.controller),onRuntimeFrame:applyRuntimeFrame}});setSyncState('local');setupAnalytics();if(startsInLobby)return;void collaboration.joinFromLocation().then(result=>{if(result?.desktopRequired)return;}).catch(()=>{setSyncState('offline');toast(collaboration.available()?'This shared project could not be opened.':'Online collaboration needs a deployed Convex backend.');});}

async function copyText(value){
  try{await navigator.clipboard.writeText(value);toast('Link copied.');}
  catch{
    const input=document.createElement('textarea');
    input.value=value;
    (document.querySelector('dialog[open]')??document.body).append(input);
    input.select();
    const copied=document.execCommand('copy');
    input.remove();
    toast(copied?'Link copied.':'Select the link to copy it manually.');
  }
}
function shareDialog(){const info=collaboration?.shareInfo?.()??{active:false,available:false,desktop:true};if(!info.desktop)return modal('Share project','<p>Realtime shared editing is available on desktop only.</p>','ONLINE');if(!info.available){modal('Share project','<p>The online backend is not connected in this development build.</p><label class="field">Convex deployment URL<input id="onlineBackendUrl" placeholder="https://your-deployment.convex.cloud"></label><div id="formError" class="form-error"></div><div class="dialog-actions"><button id="connectBackend" class="primary">Connect backend</button></div>','ONLINE');$('connectBackend').onclick=async()=>{try{await collaboration.configure($('onlineBackendUrl').value);setupAnalytics();shareDialog();}catch{return error('Enter a valid Convex deployment URL.');}};return;}if(!info.active){modal('Share project','<p>Create an anonymous shared copy of this project. You keep the owner recovery key; editor and viewer links do not require accounts.</p><div class="dialog-actions"><button id="createShared" class="primary">Create shared project</button></div>','ONLINE');$('createShared').onclick=async()=>{if(!validWorld(world))return error('Finish invalid definitions before sharing.');$('createShared').disabled=true;try{await collaboration.createOnline(world);shareDialog();toast('Shared project created. Download the recovery key.');}catch{$('createShared').disabled=false;error('The shared project could not be created.');}};return;}const linkRow=(label,value,roleName)=>value?`<label class="field">${label}<span class="share-grid"><input readonly value="${esc(value)}"><button data-copy-link="${esc(roleName)}">Copy</button></span></label>`:'';modal('Share project',`<div class="access-row"><div><strong>${esc(info.role.toUpperCase())}</strong><small>Project ${esc(info.projectId)}</small></div></div>${linkRow('Your owner link',info.ownerUrl,'owner')}${linkRow('Can edit',info.editorUrl,'editor')}${linkRow('View only',info.viewerUrl,'viewer')}<div class="inline-actions">${info.role==='owner'&&!info.editorUrl?'<button id="newEditorLink">Create editor link</button>':''}${info.role==='owner'&&!info.viewerUrl?'<button id="newViewerLink">Create viewer link</button>':''}${info.role==='owner'?'<button id="downloadRecovery">Download recovery key</button>':''}</div>`,'ONLINE / SHARING');$('dialogBody').querySelectorAll('[data-copy-link]').forEach(button=>button.onclick=()=>copyText({owner:info.ownerUrl,editor:info.editorUrl,viewer:info.viewerUrl}[button.dataset.copyLink]));if($('newEditorLink'))$('newEditorLink').onclick=async()=>{await collaboration.createAccess('editor','Editor link');shareDialog();};if($('newViewerLink'))$('newViewerLink').onclick=async()=>{await collaboration.createAccess('viewer','Viewer link');shareDialog();};if($('downloadRecovery'))$('downloadRecovery').onclick=()=>{const recovery=collaboration.recoveryData();download(recovery,(recovery.projectName||'prototeer')+'-recovery-key');};}
async function renderAccessLinks(){if(!collaboration?.isOwner()||$('dialogTitle').textContent!=='Share project')return;let host=$('accessLinks');if(!host){host=document.createElement('div');host.id='accessLinks';$('dialogBody').append(host);}try{const [grants,revisions]=await Promise.all([collaboration.listCapabilities(),collaboration.listRevisions()]);host.innerHTML='<div class="form-section">ACCESS LINKS</div>'+grants.map(grant=>`<div class="access-row"><div><strong>${esc(grant.label)}</strong><small>${esc(grant.role)} · ${grant.revokedAt?'revoked':'active'}</small></div>${grant.role!=='owner'&&!grant.revokedAt?`<button data-revoke-link="${esc(grant.id)}" data-revoke-role="${esc(grant.role)}">Revoke</button>`:''}</div>`).join('')+'<div class="form-section">SAVED REVISIONS</div>'+revisions.map(item=>`<div class="access-row"><div><strong>Revision ${item.revision}</strong><small>${esc(item.reason)} · ${esc(new Date(item.createdAt).toLocaleString())}</small></div><button data-restore-revision="${esc(item.id)}">Restore</button></div>`).join('');host.querySelectorAll('[data-revoke-link]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await collaboration.revokeCapability(button.dataset.revokeLink,button.dataset.revokeRole);shareDialog();void renderAccessLinks();toast('Access link revoked.');}catch{button.disabled=false;toast('The link could not be revoked.');}});host.querySelectorAll('[data-restore-revision]').forEach(button=>button.onclick=async()=>{button.disabled=true;try{await collaboration.restoreRevision(button.dataset.restoreRevision);toast('Saved revision restored.');$('dialog').close();}catch{button.disabled=false;toast('The revision could not be restored.');}});}catch{host.innerHTML='';}}
$('share').onclick=()=>{
  if(projectHome?.isSharedBoard()&&collaboration.isOwner()){
    modal('Share project','<button id="inviteFromBoard">Invite to project</button>','ONLINE / SHARING');
    $('inviteFromBoard').onclick=()=>{$('dialog').close();projectHome.openInvite();};
    void renderAccessLinks();
    return;
  }
  if(projectHome?.openInvite())return;
  shareDialog();void renderAccessLinks();
};

initializeCollaboration();
if(startsInLobby){
  const openBoard=data=>{adopt(data);setMode('select');switchView('board');requestDraw();};
  projectHome=globalThis.PrototeerProjectHome.start({
    api,collaboration,previewOf,
    createBoard(name){return Object.assign(createWorld(),{name});},
    openLocal:openBoard,
    async openShared(boardId,token){
      try{await collaboration.bootstrap(boardId,token,{managed:true});switchView('board');setMode('select');requestDraw();}
      catch(error){collaboration.leave({preserveLocation:true});throw error;}
    },
    async openLegacy(id){
      if(!collaboration)throw Error('online_backend_not_configured');
      const result=id?await collaboration.openKnown(id):await collaboration.joinFromLocation();
      if(result?.desktopRequired)throw Error('desktop_required');
      setMode('select');switchView('board');requestDraw();
    },
    async exitEditor(preserveLocation){
      if(collaboration?.active()){
        if(collaboration.canEdit()){
          await collaboration.flush();
          if(collaboration.hasPendingEdits())throw Error('Wait for your shared edits to sync before leaving this board.');
          if(sharedController)await collaboration.pauseSimulation();
          void collaboration.updateBoardPreview?.();
        }
        collaboration.leave({preserveLocation});
        applyRunningState(false);
        dirty=false;
        return null;
      }
      applyRunningState(false);
      const current=world,currentRevision=revision;
      if(dirty){
        if(!validWorld(current))throw Error('Finish incomplete definitions before leaving this board.');
        await api('projects/'+current.id,{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(current)});
        if(revision!==currentRevision)throw Error('The board changed during the save. Try again.');
        dirty=false;
        $('saveState').textContent='Saved';
      }
      return current;
    },
    async connect(url){
      const value=String(url??'').trim().replace(/\/$/,'');
      if(!/^https:\/\/[a-z0-9-]+\.convex\.cloud$/i.test(value))throw Error('invalid_convex_url');
      await collaboration.configure(value);
      setupAnalytics();
    },
    chooseImport:()=>$('importFile').click(),
    openDemo(){
      const demo=createDemoWorld();
      openBoard(demo);
      toolId=demo.tutorial.toolId;entityId=demo.tutorial.botId;zoneId=demo.tutorial.primaryZone;
      guideOpen=true;guideStep=0;zoom=1.45;refresh();
    },
    copy:copyText,download,toast,
    record:(kind,details)=>analytics?.record(kind,details),
  });
  $('newBlank').onclick=projectHome.newProject;
  $('projects').onclick=projectHome.lobby;
  $('reloadHouse').onclick=projectHome.launchDemo;
}
const helpWithUsageSettings=$('help').onclick;$('help').onclick=()=>{helpWithUsageSettings();if(!analyticsTransport())return;$('dialogBody').insertAdjacentHTML('beforeend',`<div class="form-section">PRIVACY</div><div class="access-row"><div><strong>Anonymous usage data</strong><small>${analyticsConsent?'Allowed':'Off'} · never includes project content or artwork</small></div><button id="changeUsageConsent">Change</button></div>`);$('changeUsageConsent').onclick=()=>{$('dialog').close();$('usageConsent').hidden=false;};};
globalThis.addEventListener?.('pagehide',()=>{void analytics?.destroy?.();},{once:true});
